/**
 * CORE-6108 review (Codex) — the settings-assistant answer text needs its
 * OWN host/path-restricted markdown renderer. `src/utils/markdown.ts`'s
 * `renderMarkdown` is shared with a dozen DocNet views (issue/comment
 * bodies, agent run cards, mission timelines, ...) that have no reason to
 * lose their own images/links — registering an assistant-only allowlist on
 * the SHARED `marked`/`DOMPurify` singletons (as an earlier version of this
 * file did) silently broke every one of them.
 *
 * This module creates its OWN isolated `Marked` and `DOMPurify` instances
 * (via `dompurify`'s factory export, `createDOMPurify(window)`) so nothing
 * here ever touches the shared renderer.
 *
 * Two content types get filtered, both against the assistant's own
 * allowlists:
 *  - `<img src>` — docs.docbits.com / the GitBook assets CDN / the
 *    screenshot bucket (isSettingsAssistantImageUrl, src/constants.ts); no
 *    `alt` also strips it. Same policy as the structured recommendation
 *    images.
 *  - `<a href>` — either an https://docs.docbits.com link, or a relative
 *    in-app path the CALLER confirms resolves to a real route (the
 *    `isValidRelativePath` callback — this module has no Vue Router of its
 *    own, so the component passes `this.$router.resolve`-backed logic in).
 *    Anything else is unwrapped to plain text — never a dead/dangerous
 *    `<a>`.
 */
import { Marked } from 'marked';
import createDOMPurify from 'dompurify';
import { Prism } from 'src/utils/prism';
import {
  isSettingsAssistantDocsUrl,
  isSettingsAssistantImageUrl,
} from 'src/constants';

const RELATIVE_PATH_RE = /^\/(?!\/)/;

const assistantMarked = new Marked({ gfm: true, breaks: true });
// marked's own renderer always emits a plain, unrestricted <a> — validation
// happens once, uniformly, in the DOMPurify hook below (the renderer has no
// access to a per-call isValidRelativePath callback; the hook does, via the
// module-level variable set at the top of each render call).
//
// CORE-6108 (PO feedback): with `gfm: true` marked autolinks a BARE URL in
// the answer text (no markdown link syntax) — for those, `text === href`
// (there was never separate link text in the source). A raw
// "https://docs.docbits.com/..." sitting in running prose read badly, so a
// bare docs URL is relabelled to a short, translated title instead; any
// link that already has its own text (real markdown `[text](url)`, or any
// non-docs href) is left alone.
let currentDocLinkLabel = 'Dokumentation';
assistantMarked.use({
  renderer: {
    link({ href, text }: { href: string; text: string }) {
      const label =
        href === text && isSettingsAssistantDocsUrl(href)
          ? currentDocLinkLabel
          : text;
      return `<a href="${href}" target="_blank" rel="noopener noreferrer">${label}</a>`;
    },
  },
});

const assistantDOMPurify = createDOMPurify(window);

// Set fresh at the top of every renderAssistantMarkdown() call. Safe as a
// module-level mutable: DOMPurify.sanitize() is fully synchronous, so there
// is never a second call's value in scope while a hook fires for this one.
let currentIsValidRelativePath: (path: string) => boolean = () => false;

function unwrapToPlainText(el: Element): void {
  const text = el.ownerDocument.createTextNode(el.textContent || '');
  el.replaceWith(text);
}

assistantDOMPurify.addHook('uponSanitizeElement', (node, data) => {
  if (data.tagName === 'img') {
    const el = node as Element;
    const src = el.getAttribute ? el.getAttribute('src') : null;
    const alt = el.getAttribute ? el.getAttribute('alt') : null;
    if (!src || !alt || !isSettingsAssistantImageUrl(src)) {
      el.remove();
    }
    return;
  }
  if (data.tagName === 'a') {
    const el = node as Element;
    const href = el.getAttribute ? el.getAttribute('href') : null;
    if (!href) {
      unwrapToPlainText(el);
      return;
    }
    if (isSettingsAssistantDocsUrl(href)) {
      // External docs link — keep as-is (marked's renderer already set
      // target=_blank + rel=noopener).
      return;
    }
    if (RELATIVE_PATH_RE.test(href) && currentIsValidRelativePath(href)) {
      // In-app relative path — drop target/rel (same-origin navigation).
      el.removeAttribute('target');
      el.removeAttribute('rel');
      return;
    }
    unwrapToPlainText(el);
  }
});

export interface RenderAssistantMarkdownOptions {
  /** Confirms a relative href resolves to a real, non-catch-all route
   * (typically backed by `this.$router.resolve` in the component). A path
   * that fails this — or isn't even shaped like a relative path, or isn't
   * the docs host — is rendered as plain text, never a dead/dangerous link. */
  isValidRelativePath?: (path: string) => boolean;
  /** The translated label a bare docs URL is relabelled to (e.g.
   * `$t('settings_assistant_doc_link')`). Defaults to the German literal so
   * a caller that doesn't pass one still gets a short label instead of a
   * raw URL, rather than a silently untranslated string. */
  docLinkLabel?: string;
}

export function renderAssistantMarkdown(
  text: string,
  options: RenderAssistantMarkdownOptions = {},
): string {
  if (!text) return '';
  currentIsValidRelativePath = options.isValidRelativePath || (() => false);
  currentDocLinkLabel = options.docLinkLabel || 'Dokumentation';

  let html = assistantMarked.parse(text) as string;

  const codeBlockRegex =
    /<pre><code class="language-(\w+)">([\s\S]*?)<\/code><\/pre>/g;
  html = html.replace(codeBlockRegex, (_match, lang, code) => {
    const grammar = Prism.languages[lang];
    if (grammar) {
      const decoded = code
        .replace(/&amp;/g, '&')
        .replace(/&lt;/g, '<')
        .replace(/&gt;/g, '>')
        .replace(/&quot;/g, '"')
        .replace(/&#39;/g, "'");
      const highlighted = Prism.highlight(decoded, grammar, lang);
      return `<pre><code class="language-${lang}">${highlighted}</code></pre>`;
    }
    return `<pre><code class="language-${lang}">${code}</code></pre>`;
  });

  return assistantDOMPurify.sanitize(html, {
    ALLOWED_TAGS: [
      'p',
      'br',
      'strong',
      'em',
      'b',
      'i',
      'u',
      'a',
      'ul',
      'ol',
      'li',
      'h1',
      'h2',
      'h3',
      'h4',
      'h5',
      'h6',
      'pre',
      'code',
      'blockquote',
      'table',
      'thead',
      'tbody',
      'tr',
      'th',
      'td',
      'hr',
      'del',
      'span',
      'div',
      'img',
    ],
    ALLOWED_ATTR: [
      'href',
      'target',
      'rel',
      'class',
      'src',
      'alt',
      'title',
      'width',
      'height',
    ],
  });
}
