<template>
  <form
    class="assistant-chat__input"
    :data-test="`${testId}-form`"
    @submit.prevent="submit"
  >
    <q-input
      :id="`${testId}-input`"
      ref="input"
      :model-value="modelValue"
      outlined
      dense
      autogrow
      hide-bottom-space
      class="flex-1 assistant-chat__input-field"
      :placeholder="placeholder"
      :disable="disabled"
      :maxlength="maxlength || undefined"
      :aria-label="placeholder"
      :data-test="`${testId}-input`"
      @update:model-value="onInput"
      @keydown.enter.exact.prevent="submit"
    >
      <template #append>
        <button
          type="submit"
          class="assistant-chat__send"
          :disabled="disabled || !modelValue.trim()"
          :aria-label="$t('settings_assistant_send')"
          :data-test="`${testId}-send`"
        >
          <Icon icon="mdi:send" width="18" height="18" />
        </button>
      </template>
    </q-input>
  </form>
</template>

<script lang="ts">
import { defineComponent } from 'vue';
import { Icon } from '@iconify/vue';

export default defineComponent({
  name: 'AssistantComposer',

  components: { Icon },

  props: {
    modelValue: {
      type: String,
      default: '',
    },
    placeholder: {
      type: String,
      default: '',
    },
    disabled: {
      type: Boolean,
      default: false,
    },
    maxlength: {
      type: Number,
      default: 0,
    },
    testId: {
      type: String,
      default: 'settings-assistant',
    },
  },

  emits: ['update:modelValue', 'submit'],

  methods: {
    onInput(value: string | number | null) {
      this.$emit('update:modelValue', value == null ? '' : String(value));
    },

    submit() {
      if (this.disabled || !this.modelValue.trim()) return;
      this.$emit('submit');
    },

    focus() {
      const input = this.$refs.input as { focus?: unknown } | undefined;
      if (input && typeof input.focus === 'function') {
        (input.focus as () => void)();
        return;
      }
      const el = (this.$el as HTMLElement | null)?.querySelector?.(
        `[data-test="${this.testId}-input"]`,
      ) as HTMLElement | null;
      el?.focus();
    },
  },
});
</script>

<style lang="scss" scoped>
.assistant-chat__input {
  display: flex;
  align-items: flex-end;
  padding: 12px 16px 14px;
  border-top: 1px solid var(--border);
}

.assistant-chat__input-field :deep(.q-field__control) {
  min-height: 40px;
  border-radius: 10px;
}

.assistant-chat__input-field :deep(.q-field__append) {
  align-self: flex-end;
  height: 40px;
}

.assistant-chat__send {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 28px;
  height: 28px;
  padding: 0;
  border: 0;
  border-radius: 6px;
  background: transparent;
  color: var(--primary);
  cursor: pointer;
  transition: color 0.15s ease, background-color 0.15s ease;

  &:hover:not(:disabled) {
    background: color-mix(in srgb, var(--primary) 10%, transparent);
  }

  &:disabled {
    color: var(--muted-foreground);
    opacity: 0.5;
    cursor: default;
  }

  &:focus-visible {
    outline: 2px solid var(--ring);
    outline-offset: 1px;
  }
}
</style>
