<template>
  <div
    class="assistant-chat__error"
    role="alert"
    :data-test="`${testId}-error`"
  >
    <p>{{ message }}</p>
    <button
      v-if="traceId"
      type="button"
      class="assistant-chat__trace"
      :data-test="`${testId}-trace-id`"
      :title="$t('login_error_trace_id_copy')"
      @click="copyTraceId"
    >
      <template v-if="copied">{{ $t('settings_assistant_trace_copied') }}</template>
      <template v-else
        >{{ $t('login_error_trace_id') }}:
        <span class="font-mono">{{ traceId }}</span></template
      >
    </button>
    <q-btn
      v-if="retryable"
      flat
      dense
      no-caps
      color="primary"
      class="mt-1 self-start"
      :disable="retryDisabled"
      :data-test="`${testId}-retry`"
      @click="$emit('retry')"
      >{{ $t('settings_assistant_retry') }}</q-btn
    >
  </div>
</template>

<script lang="ts">
import { defineComponent } from 'vue';

const COPIED_FEEDBACK_MS = 2000;

export default defineComponent({
  name: 'AssistantErrorNotice',

  props: {
    message: {
      type: String,
      required: true,
    },
    traceId: {
      type: String,
      default: '',
    },
    retryable: {
      type: Boolean,
      default: false,
    },
    retryDisabled: {
      type: Boolean,
      default: false,
    },
    testId: {
      type: String,
      default: 'settings-assistant',
    },
  },

  emits: ['retry'],

  data() {
    return {
      copied: false,
      copiedTimer: null as ReturnType<typeof setTimeout> | null,
    };
  },

  beforeUnmount() {
    if (this.copiedTimer) clearTimeout(this.copiedTimer);
  },

  methods: {
    async copyTraceId() {
      if (!this.traceId) return;
      try {
        await navigator.clipboard.writeText(this.traceId);
        this.copied = true;
        if (this.copiedTimer) clearTimeout(this.copiedTimer);
        this.copiedTimer = setTimeout(() => {
          this.copied = false;
        }, COPIED_FEEDBACK_MS);
      } catch {
        // clipboard refused
      }
    },
  },
});
</script>

