/* eslint-disable no-control-regex -- Security contract explicitly rejects ASCII control characters. */
import { parsePageVideo, parseVideoRetry, utf8Bytes, type PageVideo, type VideoRetry, type VideoOutcome } from 'src/utils/settingsAssistant/pageVideos';
/**
 * CORE-6108 — Settings-assistant conversation store.
 *
 * The bug this store fixes: `turns`/`draft` used to live in
 * SettingsAssistantPanel.vue's own `data()`. The panel is only rendered
 * `v-if="assistantAvailable && assistantPanelOpen"` in SettingsLayout.vue —
 * closing the panel, `org_based_settings` briefly flipping
 * `assistantAvailable` while it reloads, a layout remount, or an HMR update
 * during dev all destroy and recreate the component, silently wiping the
 * whole conversation with no user action at all.
 *
 * A Pinia store is a singleton for the app's lifetime, so it survives every
 * one of those remounts for free — that alone fixes the bug. Mirroring
 * `turns` (+ `conversationId`) to sessionStorage on top of that additionally
 * survives a full page reload, capped to the last MAX_TURNS so a very long
 * conversation can't grow past sessionStorage's ~5MB-per-origin quota.
 *
 * Also holds the assistant drawer's resizable width (splitter drag +
 * keyboard resize in SettingsAssistantPanel.vue) — a separate, smaller piece
 * of UI state that happens to belong to the same panel, persisted to
 * localStorage (a long-lived UI preference, not per-conversation).
 *
 * `conversationId`: the generated SDK's ChatRequest model carries an
 * optional `conversation_id` (src/generated-api-sdk/models/ChatRequest.ts) —
 * the server keys its own conversation history by it. Generated once per
 * conversation (crypto.randomUUID(), with a non-crypto fallback for
 * environments without it), sent on every chat request, and reset whenever
 * the conversation itself is reset ("Neuer Chat").
 */
import { defineStore } from 'pinia';
import { getOrgId } from 'src/utils/organization/org_id_helper';
import { getUserDetails } from 'src/utils/UserDetails';
import type {
  AssistantRole,
  AssistantSource,
  AssistantRecommendation,
} from 'src/services/settingsAssistant/settingsAssistantService';
import type {
  RuleConfirmResult,
  RulePreview,
} from 'src/services/settingsAssistant/settingsAssistantRuleService';
import type { ImportActionOffer } from 'src/utils/settingsAssistant/importActionOffers';
import type { SettingsActionOffer } from 'src/utils/settingsAssistant/settingsActionOffers';

export type ConversationRole = AssistantRole | 'system';

/**
 * CORE-6103 — a transformation rule created from a chat rule-preview card.
 * Carried by the `role: 'system'` transcript line "Regel angelegt (inaktiv)"
 * that offers "Zur Regel" and, for 15 minutes, "Rückgängig".
 */
export interface RuleCreation {
  previewId: string;
  ruleId: string;
  docType: string;
  displayName: string;
  /** What undo() takes (the API's `operation_id` / `undo_id`). */
  operationId: string;
  /** Undo refuses when the admin has since switched organizations. */
  orgIdAtCreate: string;
  createdAt: number;
  expiresAt: number;
  undone?: boolean;
}

export interface ConversationTurn {
  pageVideo?: PageVideo;
  origin?: 'page_video';
  traceId?: string;
  terminalOutcome?: VideoOutcome;
  completion?: 'complete' | 'interrupted' | 'error';
  videoRetry?: VideoRetry;
  videoUnavailable?: boolean;
  role: ConversationRole;
  content: string;
  sources?: AssistantSource[];
  recommendations?: AssistantRecommendation[];
  // `role: 'system'` only — an applied-change transcript line offering undo.
  undoId?: string;
  settingKey?: string;
  /** org_id at the moment the change was applied — the undo action refuses
   * (same as the apply dialog's own toast-undo) if the admin has since
   * switched organizations. */
  orgIdAtApply?: string;
  appliedAt?: number;
  expiresAt?: number;
  undone?: boolean;
  /** CORE-6103 — `role: 'assistant'` only: the rule_preview chunk of that
   * answer, rendered as a card with "Regel anlegen". */
  rulePreview?: RulePreview;
  /** CORE-6145 — `role: 'assistant'` only: the `import_actions` chunk of that
   * answer, rendered as one card per broken import connection with its
   * switch-off / delete actions. */
  importActions?: ImportActionOffer[];
  /** CORE-6145 — `role: 'assistant'` only: the `settings_actions` chunk of
   * that answer, a change the admin asked for, carried out by their "Yes". */
  settingsActions?: SettingsActionOffer[];
  /** Set on the preview turn once its rule was created, so the card no
   * longer offers "Regel anlegen" (the preview token is single-use). */
  ruleCreatedId?: string;
  /** `role: 'system'` only — see RuleCreation. */
  ruleCreation?: RuleCreation;
}

const STORAGE_VERSION = 2; // bumped: persisted shape changed from a bare turns array to {turns, conversationId}
const MAX_TURNS = 50;

export const DEFAULT_PANEL_WIDTH = 380;
/**
 * CORE-6108 UX review: 320px was tight enough that the header (genie icon +
 * title + "Neuer Chat" + close, all in one row) started truncating/
 * crowding. 380 is also the drawer's own default width, so the minimum
 * never has to shrink the very first render.
 */
export const MIN_PANEL_WIDTH = 380;
/**
 * CORE-6108 UX review: the max used to be min(900, 60% of the viewport) —
 * on a laptop-ish width that could still leave the PAGE CONTENT less than
 * 640px wide, uncomfortably narrow for settings forms/tables behind the
 * drawer. min(760, viewport - 640) guarantees the content side keeps at
 * least 640px, with 760 as its own separate ceiling so the drawer itself
 * never gets absurdly wide on a huge monitor either.
 */
export const MAX_PANEL_WIDTH_CAP = 760;
export const MIN_CONTENT_WIDTH_PX = 640;

/**
 * How long "Rückgängig" stays offered on an applied-change transcript line.
 * NOTE: this number (15 minutes) comes from the reviewer's citation of the
 * API's apply.py, not from anything this frontend repo can itself verify —
 * there is no expiry field on ApplyConfirmResult
 * (settingsAssistantApplyService.ts) to read it from. Kept as one named,
 * easily-corrected constant rather than scattered magic numbers.
 */
export const UNDO_WINDOW_MS = 15 * 60 * 1000;

/**
 * Subtracted from EITHER expiry source — the client estimate AND a real
 * server `expires_at` alike (CORE-6108 review round 2: an earlier version
 * of this only applied it to the client estimate, but clock drift between
 * this browser and the API is exactly as real a risk against a server
 * timestamp compared against `Date.now()` here as it is against a pure
 * client guess). Also covers the panel's own 5s countdown tick. Both bias
 * toward the client still showing "Rückgängig" a little after the server
 * would actually refuse it — erring toward hiding it slightly early is the
 * safe direction; `undoAppliedChange`'s own deadline re-check is the hard
 * backstop either way.
 */
export const UNDO_CLIENT_ESTIMATE_SAFETY_MARGIN_MS = 30 * 1000;

function currentUserId(): string {
  try {
    const details = getUserDetails() as { id?: string | number } | undefined;
    return details?.id != null && details.id !== '' ? String(details.id) : 'anon';
  } catch {
    return 'anon';
  }
}

/** Scoped per org+user so switching organizations or users on the same
 * browser never shows one person's conversation to another. */
function conversationStorageKey(): string {
  const orgId = getOrgId() || 'no-org';
  return `docbits_settings_assistant_conversation_v${STORAGE_VERSION}_${orgId}_${currentUserId()}`;
}

function panelWidthStorageKey(): string {
  return `docbits_settings_assistant_panel_width_v${STORAGE_VERSION}_${currentUserId()}`;
}

function isConversationTurn(value: unknown): value is ConversationTurn {
  if (!value || typeof value !== 'object') return false;
  const turn = value as Partial<ConversationTurn>;
  return (
    (turn.role === 'user' || turn.role === 'assistant' || turn.role === 'system') &&
    typeof turn.content === 'string'
  );
}

/**
 * crypto.randomUUID() where available. The fallback (older browsers/test
 * runners without it) must ALSO be a real RFC 4122 v4 UUID — the API
 * validates `conversation_id` against a UUID pattern
 * (routers/settings_assistant.py: `Field(None, pattern=_UUID_RE)`) and
 * rejects anything else with a 422. A `conv-<timestamp>-<random>`-shaped
 * id (this function's first cut) would have broken every request from a
 * browser without crypto.randomUUID.
 */
function generateConversationId(): string {
  try {
    if (
      typeof crypto !== 'undefined' &&
      typeof crypto.randomUUID === 'function'
    ) {
      return crypto.randomUUID();
    }
  } catch {
    // fall through to the fallback below
  }
  return uuidV4Fallback();
}

/** RFC 4122 v4 UUID built from crypto.getRandomValues (broader browser
 * support than crypto.randomUUID — Safari <15.4, older Firefox/Chrome),
 * with Math.random as the last resort so this can never throw. */
function uuidV4Fallback(): string {
  const bytes = new Uint8Array(16);
  try {
    if (typeof crypto !== 'undefined' && typeof crypto.getRandomValues === 'function') {
      crypto.getRandomValues(bytes);
    } else {
      for (let i = 0; i < 16; i++) bytes[i] = Math.floor(Math.random() * 256);
    }
  } catch {
    for (let i = 0; i < 16; i++) bytes[i] = Math.floor(Math.random() * 256);
  }
  // Per RFC 4122 §4.4: set the version (4) and variant (10) bits.
  bytes[6] = (bytes[6] & 0x0f) | 0x40;
  bytes[8] = (bytes[8] & 0x3f) | 0x80;
  const hex = Array.from(bytes, (b) => b.toString(16).padStart(2, '0'));
  return (
    hex.slice(0, 4).join('') +
    '-' +
    hex.slice(4, 6).join('') +
    '-' +
    hex.slice(6, 8).join('') +
    '-' +
    hex.slice(8, 10).join('') +
    '-' +
    hex.slice(10, 16).join('')
  );
}

/** Preserve existing cards, but never spread untrusted video metadata into storage. */
export function projectConversationTurn(turn: ConversationTurn): ConversationTurn {
  const { pageVideo, origin, traceId, terminalOutcome, completion, videoRetry, videoUnavailable, ...existing } = turn;
  const result: ConversationTurn = { ...existing };
  if (origin === 'page_video' || pageVideo !== undefined) result.origin = 'page_video';
  const parsed = parsePageVideo(pageVideo);
  if (parsed) result.pageVideo = parsed;
  else if (pageVideo !== undefined || videoUnavailable === true) result.videoUnavailable = true;
  if (typeof traceId === 'string' && traceId.length <= 256 && !/[\x00-\x20\x7f]/.test(traceId)) result.traceId = traceId;
  if (['answered', 'nothing_found', 'error'].includes(terminalOutcome)) result.terminalOutcome = terminalOutcome;
  if (['complete', 'interrupted', 'error'].includes(completion)) result.completion = completion;
  const retry = parseVideoRetry(videoRetry);
  if (retry && result.origin === 'page_video') result.videoRetry = retry;
  return result;
}
export const MAX_CONVERSATION_BYTES = 512 * 1024;
export function conversationScope(): string { return conversationStorageKey(); }

interface PersistedConversation {
  turns: ConversationTurn[];
  conversationId: string;
}

function readPersistedConversation(): PersistedConversation {
  try {
    const raw = window.sessionStorage.getItem(conversationStorageKey());
    if (raw && utf8Bytes(raw) <= MAX_CONVERSATION_BYTES) {
      const parsed: unknown = JSON.parse(raw);
      if (parsed && typeof parsed === 'object' && !Array.isArray(parsed)) {
        const candidate = parsed as Partial<PersistedConversation>;
        const turns = Array.isArray(candidate.turns)
          ? candidate.turns.filter(isConversationTurn).slice(-MAX_TURNS).map(projectConversationTurn)
          : [];
        const conversationId =
          typeof candidate.conversationId === 'string' && candidate.conversationId
            ? candidate.conversationId
            : generateConversationId();
        return { turns, conversationId };
      }
    }
  } catch {
    // Corrupted JSON, sessionStorage disabled (private browsing), or quota
    // errors on read — start fresh rather than throw.
  }
  return { turns: [], conversationId: generateConversationId() };
}

/** The upper bound of the resizable range for a given viewport —
 * min(MAX_PANEL_WIDTH_CAP, viewport - MIN_CONTENT_WIDTH_PX) so the page
 * content behind the drawer always keeps at least MIN_CONTENT_WIDTH_PX,
 * with MAX_PANEL_WIDTH_CAP as its own ceiling. Exported on its own (not
 * just via clampPanelWidth) so the panel's `aria-valuemax` and End-key
 * handler can read the same bound. */
export function panelWidthMax(
  viewportWidth: number = typeof window !== 'undefined'
    ? window.innerWidth
    : 1440,
): number {
  return Math.max(
    MIN_PANEL_WIDTH,
    Math.min(MAX_PANEL_WIDTH_CAP, Math.round(viewportWidth - MIN_CONTENT_WIDTH_PX)),
  );
}

/** Clamp to the bounds the splitter drag and keyboard resize both respect.
 * Exported so the panel's drag/keyboard handlers and this store's own
 * persistence agree on exactly one definition. */
export function clampPanelWidth(
  px: number,
  viewportWidth: number = typeof window !== 'undefined'
    ? window.innerWidth
    : 1440,
): number {
  return Math.min(
    Math.max(Math.round(px), MIN_PANEL_WIDTH),
    panelWidthMax(viewportWidth),
  );
}

function readPersistedPanelWidth(): number {
  try {
    const raw = window.localStorage.getItem(panelWidthStorageKey());
    if (!raw) return DEFAULT_PANEL_WIDTH;
    const value = Number(raw);
    if (!Number.isFinite(value)) return DEFAULT_PANEL_WIDTH;
    return clampPanelWidth(value);
  } catch {
    return DEFAULT_PANEL_WIDTH;
  }
}

export interface SettingsAssistantConversationState {
  turns: ConversationTurn[];
  draft: string;
  panelWidth: number;
  conversationId: string;
}

export const useSettingsAssistantConversationStore = defineStore(
  'settingsAssistantConversation',
  {
    // Hydration runs once, when this singleton store is first used (e.g. the
    // first time the panel mounts) — org/user id are already resolved by
    // then, since the panel only ever renders on an authenticated /settings
    // page.
    state: (): SettingsAssistantConversationState => {
      const persisted = readPersistedConversation();
      return {
        turns: persisted.turns,
        draft: '',
        panelWidth: readPersistedPanelWidth(),
        conversationId: persisted.conversationId,
      };
    },

    actions: {
      setDraft(value: string) {
        this.draft = value;
      },

      addTurn(turn: ConversationTurn) {
        this.turns.push(turn);
        if (this.turns.length > MAX_TURNS) {
          this.turns.splice(0, this.turns.length - MAX_TURNS);
        }
        this.persistConversation();
      },

      /** An applied-change transcript line (CORE-6109 apply flow), offering
       * "Rückgängig" until `UNDO_WINDOW_MS` after it was applied. */
      addAppliedChangeTurn(params: {
        content: string;
        undoId: string;
        settingKey: string;
        orgIdAtApply: string;
        /** The server's own undo-expiry, when the confirm response
         * provides one — preferred over the client-side UNDO_WINDOW_MS
         * estimate whenever it's available. */
        expiresAt?: number;
      }) {
        const appliedAt = Date.now();
        this.turns.push({
          role: 'system',
          content: params.content,
          undoId: params.undoId,
          settingKey: params.settingKey,
          orgIdAtApply: params.orgIdAtApply,
          appliedAt,
          // CORE-6108 review round 2: the safety margin applies to BOTH
          // sources, not just the client estimate — see the constant's own
          // doc comment.
          expiresAt:
            (typeof params.expiresAt === 'number'
              ? params.expiresAt
              : appliedAt + UNDO_WINDOW_MS) - UNDO_CLIENT_ESTIMATE_SAFETY_MARGIN_MS,
          undone: false,
        });
        if (this.turns.length > MAX_TURNS) {
          this.turns.splice(0, this.turns.length - MAX_TURNS);
        }
        this.persistConversation();
      },

      /** Marks the transcript line for `undoId` as undone (hides its
       * "Rückgängig" button) after a successful undo call. */
      markChangeUndone(undoId: string) {
        const turn = this.turns.find(
          (t) => t.role === 'system' && t.undoId === undoId,
        );
        if (turn) turn.undone = true;
        this.persistConversation();
      },

      /**
       * CORE-6103 — the rule of the preview card `previewId` was created:
       * marks that card as done and appends the "Regel angelegt (inaktiv)"
       * transcript line with its undo window (server `expires_at`, minus the
       * same safety margin as the settings apply flow).
       */
      recordRuleCreated(params: {
        previewId: string;
        result: RuleConfirmResult;
        orgIdAtCreate: string;
        content: string;
      }) {
        const { previewId, result } = params;
        const previewTurn = this.turns.find(
          (t) => t.rulePreview?.preview_id === previewId,
        );
        if (previewTurn) previewTurn.ruleCreatedId = result.rule_id;
        const createdAt = Date.now();
        const serverExpiresAt = result.expires_at
          ? Date.parse(result.expires_at)
          : NaN;
        this.turns.push({
          role: 'system',
          content: params.content,
          ruleCreation: {
            previewId,
            ruleId: result.rule_id,
            docType: result.doc_type,
            displayName: result.display_name,
            operationId: result.operation_id || result.undo_id,
            orgIdAtCreate: params.orgIdAtCreate,
            createdAt,
            expiresAt:
              (Number.isFinite(serverExpiresAt)
                ? serverExpiresAt
                : createdAt + UNDO_WINDOW_MS) - UNDO_CLIENT_ESTIMATE_SAFETY_MARGIN_MS,
            undone: false,
          },
        });
        if (this.turns.length > MAX_TURNS) {
          this.turns.splice(0, this.turns.length - MAX_TURNS);
        }
        this.persistConversation();
      },

      /** CORE-6103 — the created rule `operationId` was undone. */
      markRuleUndone(operationId: string) {
        const turn = this.turns.find(
          (t) => t.ruleCreation?.operationId === operationId,
        );
        if (turn?.ruleCreation) turn.ruleCreation.undone = true;
        this.persistConversation();
      },

      /** "Neuer Chat" — an intentional, user-initiated reset. Distinct from
       * the accidental wipes this store exists to prevent. Also starts a
       * fresh conversation_id, since a new conversation is exactly that. */
      clearConversation() {
        this.turns = [];
        this.draft = '';
        this.conversationId = generateConversationId();
        this.persistConversation();
      },

      persistConversation() {
        try {
          const storedTurns = this.turns.map(projectConversationTurn);
          const serialize = () => JSON.stringify({ turns: storedTurns, conversationId: this.conversationId });
          while (utf8Bytes(serialize()) > MAX_CONVERSATION_BYTES && storedTurns.length) {
            // Remove an entire oldest exchange, never leave its assistant orphaned.
            let next = storedTurns.findIndex((t, i) => i > 0 && t.role === 'user');
            if (next < 0) {
              for (const t of storedTurns) { if (t.pageVideo) { delete t.pageVideo; t.videoUnavailable = true; } }
              if (utf8Bytes(serialize()) <= MAX_CONVERSATION_BYTES) break;
              next = storedTurns.length;
            }
            storedTurns.splice(0, next);
          }
          window.sessionStorage.setItem(
            conversationStorageKey(),
            JSON.stringify({
              turns: storedTurns,
              conversationId: this.conversationId,
            }),
          );
        } catch {
          // Quota exceeded or sessionStorage unavailable — the conversation
          // still lives in the store for this tab; only the reload-survival
          // mirror is lost.
        }
      },

      setPanelWidth(px: number) {
        this.panelWidth = clampPanelWidth(px);
        try {
          window.localStorage.setItem(
            panelWidthStorageKey(),
            String(this.panelWidth),
          );
        } catch {
          // Best-effort persistence only — the width still applies for the
          // rest of this session.
        }
      },

      resetPanelWidth() {
        this.setPanelWidth(DEFAULT_PANEL_WIDTH);
      },
    },
  },
);
