<template>
  <div
    class="assistant-chat__grip"
    :class="{ 'assistant-chat__grip--active': isResizing }"
    role="separator"
    aria-orientation="vertical"
    tabindex="0"
    :aria-label="ariaLabel || $t('settings_assistant_resize_handle')"
    :aria-valuenow="Math.round(modelValue)"
    :aria-valuemin="min"
    :aria-valuemax="max"
    :data-test="`${testId}-resize-handle`"
    @pointerdown="onGripPointerDown"
    @keydown="onGripKeydown"
    @dblclick="$emit('reset')"
  ></div>
</template>

<script lang="ts">
import { defineComponent } from 'vue';

const RESIZE_KEYBOARD_STEP = 16;

export default defineComponent({
  name: 'AssistantResizeGrip',

  props: {
    modelValue: {
      type: Number,
      required: true,
    },
    min: {
      type: Number,
      required: true,
    },
    max: {
      type: Number,
      required: true,
    },
    ariaLabel: {
      type: String,
      default: '',
    },
    testId: {
      type: String,
      default: 'settings-assistant',
    },
  },

  emits: ['update:modelValue', 'reset'],

  data() {
    return {
      isResizing: false,
      resizeStartX: 0,
      resizeStartWidth: 0,
    };
  },

  beforeUnmount() {
    window.removeEventListener('pointermove', this.onGripPointerMove);
    window.removeEventListener('pointerup', this.onGripPointerUp);
  },

  methods: {
    clamp(px: number): number {
      return Math.min(Math.max(px, this.min), Math.max(this.min, this.max));
    },

    // The grip sits on the left edge of a right-anchored panel: dragging left widens it.
    onGripPointerDown(event: PointerEvent) {
      if (typeof event.button === 'number' && event.button !== 0) return;
      this.isResizing = true;
      this.resizeStartX = event.clientX;
      this.resizeStartWidth = this.modelValue;
      try {
        (event.currentTarget as HTMLElement | null)?.setPointerCapture?.(
          event.pointerId,
        );
      } catch {
        // no pointer capture (jsdom); the window listeners still track the drag
      }
      window.addEventListener('pointermove', this.onGripPointerMove);
      window.addEventListener('pointerup', this.onGripPointerUp, {
        once: true,
      });
      event.preventDefault();
    },

    onGripPointerMove(event: PointerEvent) {
      if (!this.isResizing) return;
      const delta = this.resizeStartX - event.clientX;
      this.$emit('update:modelValue', this.clamp(this.resizeStartWidth + delta));
    },

    onGripPointerUp() {
      this.isResizing = false;
      window.removeEventListener('pointermove', this.onGripPointerMove);
    },

    onGripKeydown(event: KeyboardEvent) {
      let next: number | null = null;
      switch (event.key) {
        case 'ArrowLeft':
          next = this.modelValue + RESIZE_KEYBOARD_STEP;
          break;
        case 'ArrowRight':
          next = this.modelValue - RESIZE_KEYBOARD_STEP;
          break;
        case 'Home':
          next = this.min;
          break;
        case 'End':
          next = this.max;
          break;
        default:
          return;
      }
      event.preventDefault();
      this.$emit('update:modelValue', this.clamp(next));
    },
  },
});
</script>

<style lang="scss" scoped>
// A 6px hit area straddling the panel's left border; the bar shows on hover/focus/drag.
.assistant-chat__grip {
  position: absolute;
  top: 0;
  bottom: 0;
  left: -3px;
  width: 6px;
  cursor: col-resize;
  z-index: 5;
  touch-action: none;

  &::after {
    content: '';
    position: absolute;
    top: 50%;
    left: 50%;
    transform: translate(-50%, -50%);
    width: 3px;
    height: 32px;
    border-radius: 999px;
    background: transparent;
    transition: background-color 0.15s ease;
  }

  &:hover::after,
  &:focus-visible::after,
  &--active::after {
    background: var(--primary);
  }

  &:focus-visible {
    outline: none;
  }
}
</style>
