/**
 * CORE-6145 — client for the settings changes the Settings Assistant prepares in
 * the chat (doc2-api `POST /v3/settings-assistant/actions/{preview,confirm,undo}`):
 * document types on/off and renaming an access group.
 *
 * Same three steps as the apply and import flows: `preview` writes nothing,
 * `confirm` only ever runs from the admin's own click on "Yes", `undo` restores
 * the previous state within 15 minutes. Errors are the apply flow's
 * `ApplyRequestError` (status + errorCode).
 *
 * The generated SDK does not have these routes until its next regeneration, so
 * this calls the generated core `request` the way a generated service does.
 */
import { OpenAPI } from 'src/generated-api-sdk/core/OpenAPI';
import { request as __request } from 'src/generated-api-sdk/core/request';
import { getOrgId } from 'src/utils/organization/org_id_helper';
import { toApplyRequestError } from 'src/services/settingsAssistant/settingsAssistantApplyService';
import type { SettingsActionKind } from 'src/utils/settingsAssistant/settingsActionOffers';

export interface SettingsActionConfirmResult {
  success: boolean;
  kind: SettingsActionKind;
  /** null: the change cannot be undone. */
  undo_id: string | null;
  undo_expires_in_seconds?: number;
}

async function post<T>(
  path: string,
  body: Record<string, unknown>,
): Promise<T> {
  try {
    return (await __request(OpenAPI, {
      method: 'POST',
      url: `/v3/settings-assistant/actions/${path}`,
      headers: { 'X-ORG-ID': getOrgId() },
      body,
      mediaType: 'application/json',
    })) as T;
  } catch (error) {
    throw toApplyRequestError(error);
  }
}

export const settingsAssistantSettingsActionService = {
  /** Dry-run only — writes nothing. */
  preview(kind: SettingsActionKind, params: Record<string, unknown>) {
    return post<unknown>('preview', { kind, params });
  },

  /** Carries the change out. Only ever call this as the direct result of the
   * admin's own click on "Yes". */
  confirm(previewId: string) {
    return post<SettingsActionConfirmResult>('confirm', {
      preview_id: previewId,
    });
  },

  /** Restores the state a confirmed change replaced. */
  undo(undoId: string) {
    return post<{ success: boolean }>('undo', { undo_id: undoId });
  },
};

export default settingsAssistantSettingsActionService;
