import { aiModelList, resolveKnownAiTierLabel } from 'src/constants';
import { translated, type Translate } from 'src/utils/translate';

/**
 * CORE-6108: customers may only ever see the AI tier names (Full, Fast,
 * Nexus, Nexus Flash, Auto, Auto Nexus) — never the internal model id behind
 * them ("gpt-6-sol", "glm-5.3-flash", …). doc2-api converts server-side;
 * this is the web's second layer for everything the settings assistant
 * renders: recommendation cards, the apply dialog and the chat text itself.
 */

/** Neutral label for an id that maps to no known tier. */
export const UNKNOWN_AI_MODEL_KEY = 'settings_assistant_ai_model_unknown';
const UNKNOWN_AI_MODEL_FALLBACK = 'Older/custom AI model';

/** Settings whose value is an AI model id: AI_MODEL, SUPPLIER_AI_MODEL_OVERRIDE,
 * TABLE_AI_MODEL, … Structured table AI configs are caught by the value
 * shape instead (their model field is formatted without a key), so a
 * sibling flag like `enabled: true` still renders as on/off. */
export function isAiModelSettingKey(settingKey?: string | null): boolean {
  if (!settingKey) return false;
  return /ai_?model|model_override/i.test(settingKey);
}

// Vendor model-id shapes, optionally as a fine-tune (ft:<base>:…). A vendor
// word alone ("Claude", "GPT") is prose, not an id — an id needs a hyphen or
// a version digit right after the vendor prefix.
const MODEL_ID_SOURCE =
  '(?:ft:)?(?:(?:gpt|glm|claude|mistral|o\\d)-[A-Za-z0-9._:-]*|qwen[-\\d][A-Za-z0-9._:-]*)';
const MODEL_ID_EXACT = new RegExp(`^${MODEL_ID_SOURCE}$`, 'i');
// Not preceded by a word char, "-" or "/" (so "foo-gpt-x" or a URL path
// segment is left alone).
const MODEL_ID_IN_TEXT = new RegExp(`(?<![\\w/-])${MODEL_ID_SOURCE}`, 'gi');

/** Whether a raw value is shaped like an internal model id (every known
 * tier id and legacy id is; "auto" deliberately is not — other settings use
 * that word too, so it is only mapped under an AI model setting key). */
export function looksLikeAiModelId(value: string): boolean {
  return MODEL_ID_EXACT.test(value.trim());
}

/** Tier label for a model id; unknown ids get the neutral localized label,
 * never the raw id. A value that already IS a tier label (API #11801/#11819
 * sends the AI_MODEL card as value_type "enum" with current_value "Full")
 * is returned as that label — never looked up as a translation key. */
export function aiModelDisplayLabel(modelId: string, t: Translate): string {
  const trimmed = modelId.trim();
  const tierLabel = aiModelList.find(
    (item) => item.label.toLowerCase() === trimmed.toLowerCase(),
  );
  if (tierLabel) return tierLabel.label;
  const known = resolveKnownAiTierLabel(trimmed);
  if (known) return known;
  return translated(t, UNKNOWN_AI_MODEL_KEY, UNKNOWN_AI_MODEL_FALLBACK);
}

/**
 * Replace every model id in chat text with its tier label. Runs on the
 * whole message on every render (the streamed text is re-rendered from its
 * accumulated buffer), so a half-streamed id ("gpt-6-s") is already masked —
 * as the neutral label until the rest arrives, then as its tier.
 */
export function sanitizeAiModelIds(text: string, t: Translate): string {
  if (!text) return text;
  return text.replace(MODEL_ID_IN_TEXT, (match) => {
    // Sentence punctuation directly after an id belongs to the sentence.
    const id = match.replace(/[.:_-]+$/, '');
    const tail = match.slice(id.length);
    return aiModelDisplayLabel(id, t) + tail;
  });
}
