/**
 * CORE-6109 — client for the Settings-Assistant Wave 1 apply flow
 * (preview / confirm / undo, doc2-api `POST /v3/settings-assistant/apply/*`).
 *
 * DOCB-SDK-migration: these endpoints now have a generated client
 * (src/generated-api-sdk/services/SettingsAssistantApplyService.ts, from
 * openapi-typescript-codegen — see scripts/update-sdks.sh) — the earlier
 * hand-rolled `fetch()` version existed only because the endpoints were
 * brand new and hadn't been through a regen yet. Routes through the
 * generated `SettingsAssistantApplyService` static methods now, so a
 * backend path/param rename shows up as a compile error here instead of a
 * silent runtime 404 (see settingsAssistantService.ts's chat path for
 * exactly that failure mode — /v3/settings-assistant/chat vs. the API's
 * actual /settings-assistant/chat).
 *
 * The public contract (ApplyRequestError with .status/.errorCode,
 * Preview/Confirm/UndoResult shapes) is unchanged on purpose —
 * SettingsAssistantApplyDialog.vue's `instanceof ApplyRequestError` /
 * `err.status === 409` handling and its `result.applied`/`result.verified`
 * checks depend on it.
 */
// Direct file imports, NOT the src/generated-api-sdk barrel (index.ts
// re-exports 124 generated service classes + 660+ models) — CLAUDE.md's
// barrel-import rule: a barrel import pulls the whole SDK into whatever
// chunk loads this service, not just the two symbols actually used here.
import { SettingsAssistantApplyService as GeneratedSettingsAssistantApplyService } from 'src/generated-api-sdk/services/SettingsAssistantApplyService';
import { ApiError } from 'src/generated-api-sdk/core/ApiError';
import { getOrgId } from 'src/utils/organization/org_id_helper';
import { messageFromErrorBody } from 'src/utils/settingsAssistant/apiErrorMessage';
import { TRACE_BODY_FIELD } from 'src/utils/errorTraceId';

export interface ApplyPreviewResult {
  preview_id: string;
  setting_key: string;
  label_key: string;
  scope: string;
  current_value: unknown;
  proposed_value: unknown;
  expires_in_seconds: number;
  /** Not part of the deployed contract yet (2026-09-29) — see the
   * matching note on AssistantRecommendation.value_type in
   * settingsAssistantService.ts. Cast through from whatever JSON the
   * generated client returns, so this is a no-op today and picks the
   * field up automatically once the backend adds it. */
  value_type?: string;
}

export interface ApplyConfirmResult {
  applied: boolean;
  verified: boolean;
  setting_key: string;
  old_value: unknown;
  new_value: unknown;
  undo_id: string;
}

export interface ApplyUndoResult {
  applied: boolean;
  verified: boolean;
  setting_key: string;
  restored_value: unknown;
}

/** A failed request, with the HTTP status and doc2-api's `error_code` so
 * the dialog can special-case 409 (PREVIEW_STALE) without string-matching
 * the message. */
export class ApplyRequestError extends Error {
  status?: number;
  errorCode?: string;
  traceId: string;

  constructor(
    message: string,
    status?: number,
    errorCode?: string,
    traceId = '',
  ) {
    super(message);
    this.name = 'ApplyRequestError';
    this.status = status;
    this.errorCode = errorCode;
    this.traceId = traceId;
  }
}

/**
 * The generated SDK's own `catchErrorCodes` throws ApiError with a generic
 * per-status label as `.message` ("Validation Error", "The setting changed
 * since it was previewed", ...) — NOT the server's actual response body.
 * The real message/error_code doc2-api sent live on `ApiError.body`. This
 * re-wraps that into the same ApplyRequestError shape callers already
 * handle, so SettingsAssistantApplyDialog.vue's error handling needs zero
 * changes.
 *
 * CORE-6108 review: `String(body.message || body.detail || ...)` used to
 * render literally `"[object Object],[object Object]"` for a 422 —
 * FastAPI's validation-error `detail` is an ARRAY of `{loc, msg, type}`
 * objects, not a string; `Array.prototype.toString()` joins each element
 * via `Object.prototype.toString()`. `messageFromErrorBody` extracts the
 * real `.msg` text (or the `detail` string, when it already is one).
 */
export function toApplyRequestError(error: unknown): ApplyRequestError {
  if (error instanceof ApiError) {
    const body = (error.body ?? {}) as Record<string, unknown>;
    const message = messageFromErrorBody(body, `HTTP ${error.status}`);
    const traceId = String(body[TRACE_BODY_FIELD] || '');
    return new ApplyRequestError(
      message,
      error.status,
      typeof body.error_code === 'string' ? body.error_code : undefined,
      traceId,
    );
  }
  return new ApplyRequestError(
    error instanceof Error ? error.message : String(error),
  );
}

export const settingsAssistantApplyService = {
  /** Dry-run only — writes nothing. */
  async preview(
    settingKey: string,
    proposedValue: boolean | string,
  ): Promise<ApplyPreviewResult> {
    try {
      return (await GeneratedSettingsAssistantApplyService.applyPreviewV3SettingsAssistantApplyPreviewPost(
        {
          requestBody: {
            setting_key: settingKey,
            proposed_value: proposedValue,
          },
          xOrgId: getOrgId(),
        },
      )) as ApplyPreviewResult;
    } catch (error) {
      throw toApplyRequestError(error);
    }
  },

  /** Writes the setting. Only ever call this as the direct result of the
   * user's own click on the dialog's confirm button. */
  async confirm(previewId: string): Promise<ApplyConfirmResult> {
    try {
      return (await GeneratedSettingsAssistantApplyService.applyConfirmV3SettingsAssistantApplyConfirmPost(
        {
          requestBody: { preview_id: previewId },
          xOrgId: getOrgId(),
        },
      )) as ApplyConfirmResult;
    } catch (error) {
      throw toApplyRequestError(error);
    }
  },

  /** Restores the value a confirmed change replaced. */
  async undo(undoId: string): Promise<ApplyUndoResult> {
    try {
      return (await GeneratedSettingsAssistantApplyService.applyUndoV3SettingsAssistantApplyUndoPost(
        {
          requestBody: { undo_id: undoId },
          xOrgId: getOrgId(),
        },
      )) as ApplyUndoResult;
    } catch (error) {
      throw toApplyRequestError(error);
    }
  },
};

export default settingsAssistantApplyService;
