<template>
  <div
    class="assistant-chat__bubble"
    :class="{
      'assistant-chat__bubble--user': role === 'user',
      'assistant-chat__bubble--assistant': role === 'assistant',
      'assistant-chat__bubble--system': role === 'system',
    }"
    :data-test="dataTest || `${testId}-turn-${role}`"
  >
    <slot>
      <div
        v-if="role === 'assistant' && renderMarkdown"
        class="assistant-chat__markdown"
        v-html="renderMarkdown(content)"
      ></div>
      <template v-else>{{ content }}</template>
    </slot>

    <slot name="after"></slot>

    <button
      v-if="copyable && role === 'assistant' && content"
      type="button"
      class="assistant-chat__copy"
      :aria-label="$t('settings_assistant_copy')"
      :data-test="`${testId}-copy`"
      @click="copy"
    >
      <Icon icon="mdi:content-copy" width="16" height="16" />
    </button>
  </div>
</template>

<script lang="ts">
import { defineComponent, type PropType } from 'vue';
import { Icon } from '@iconify/vue';

export type AssistantBubbleRole = 'user' | 'assistant' | 'system';

export default defineComponent({
  name: 'AssistantBubble',

  components: { Icon },

  props: {
    role: {
      type: String as PropType<AssistantBubbleRole>,
      required: true,
    },
    content: {
      type: String,
      default: '',
    },
    copyable: {
      type: Boolean,
      default: false,
    },
    // Must return sanitized HTML; each assistant brings its own link checks.
    renderMarkdown: {
      type: Function as PropType<(text: string) => string>,
      default: null,
    },
    dataTest: {
      type: String,
      default: '',
    },
    testId: {
      type: String,
      default: 'settings-assistant',
    },
  },

  emits: ['copied'],

  methods: {
    async copy() {
      try {
        await navigator.clipboard.writeText(this.content);
        this.$emit('copied');
      } catch {
        // clipboard refused (older app views)
      }
    },
  },
});
</script>

