<template>
  <header class="assistant-chat__header">
    <div class="flex items-center gap-2 min-w-0">
      <Icon
        icon="docbits:genie-lamp"
        width="18"
        height="18"
        class="text-primary shrink-0"
      />
      <!-- a div with the heading role: a global !important h2 rule would override the size -->
      <div
        class="assistant-chat__title text-lg font-semibold leading-tight"
        role="heading"
        aria-level="2"
      >
        {{ title }}
      </div>
    </div>
    <div class="flex items-center gap-1 shrink-0">
      <q-btn
        v-if="showPopOut"
        flat
        round
        dense
        :aria-label="$t('new_window')"
        :data-test="`${testId}-pop-out`"
        @click="$emit('pop-out')"
      >
        <Icon icon="mdi:open-in-new" width="18" height="18" />
        <q-tooltip>{{ $t('new_window') }}</q-tooltip>
      </q-btn>
      <q-btn
        v-if="showNewChat"
        flat
        round
        dense
        :disable="newChatDisabled"
        :aria-label="$t('settings_assistant_new_chat')"
        :data-test="`${testId}-new-chat`"
        @click="$emit('new-chat')"
      >
        <Icon icon="mdi:chat-plus-outline" width="18" height="18" />
        <q-tooltip>{{ $t('settings_assistant_new_chat') }}</q-tooltip>
      </q-btn>
      <q-btn
        flat
        round
        dense
        :aria-label="closeLabel || $t('settings_assistant_close')"
        :data-test="`${testId}-close`"
        @click="$emit('close')"
      >
        <Icon icon="mdi:close" width="18" height="18" />
      </q-btn>
    </div>
  </header>
</template>

<script lang="ts">
import { defineComponent } from 'vue';
import { Icon } from '@iconify/vue';

export default defineComponent({
  name: 'AssistantHeader',

  components: { Icon },

  props: {
    title: {
      type: String,
      required: true,
    },
    showNewChat: {
      type: Boolean,
      default: true,
    },
    /**
     * CORE-6161: opt-in, so the Settings Assistant header stays pixel-identical.
     * The validation panel shows it in the docked sidebar only.
     */
    showPopOut: {
      type: Boolean,
      default: false,
    },
    newChatDisabled: {
      type: Boolean,
      default: false,
    },
    closeLabel: {
      type: String,
      default: '',
    },
    testId: {
      type: String,
      default: 'settings-assistant',
    },
  },

  emits: ['new-chat', 'close', 'pop-out'],
});
</script>

