export type VideoOutcome = 'answered' | 'nothing_found' | 'error';
export const VIDEO_ORIGIN =
  'https://docbits-videos.fra1.cdn.digitaloceanspaces.com';
export const utf8Bytes = (text: string): number =>
  new TextEncoder().encode(text).length;
// Interpret only the fixed contract vocabulary: no runtime code generation / unsafe-eval.
type Shape = {
  $ref?: string;
  const?: unknown;
  enum?: unknown[];
  type?: string;
  required?: string[];
  properties?: Record<string, Shape>;
  additionalProperties?: boolean;
  minLength?: number;
  maxLength?: number;
  pattern?: string;
  minimum?: number;
  maximum?: number;
  minItems?: number;
  maxItems?: number;
  items?: Shape;
};
function matchesShape(value: unknown, shape: Shape): boolean {
  if (shape.$ref)
    return matchesShape(
      value,
      schema.$defs[shape.$ref.split('/').pop()] as Shape,
    );
  if ('const' in shape && value !== shape.const) return false;
  if (shape.enum && !shape.enum.includes(value)) return false;
  if (shape.type === 'object') {
    if (!value || typeof value !== 'object' || Array.isArray(value))
      return false;
    const object = value as Record<string, unknown>;
    return (
      (shape.required || []).every((k) =>
        Object.prototype.hasOwnProperty.call(object, k),
      ) &&
      Object.keys(object).every(
        (k) =>
          !!shape.properties?.[k] &&
          matchesShape(object[k], shape.properties[k]),
      )
    );
  }
  if (shape.type === 'array')
    return (
      Array.isArray(value) &&
      value.length >= (shape.minItems || 0) &&
      value.length <= (shape.maxItems || Infinity) &&
      value.every((v) => matchesShape(v, shape.items))
    );
  if (shape.type === 'string')
    return (
      typeof value === 'string' &&
      [...value].length >= (shape.minLength || 0) &&
      [...value].length <= (shape.maxLength || Infinity) &&
      (!shape.pattern || new RegExp(shape.pattern).exec(value)?.[0] === value)
    );
  if (shape.type === 'integer')
    return (
      Number.isInteger(value) &&
      (value as number) >= (shape.minimum ?? -Infinity) &&
      (value as number) <= (shape.maximum ?? Infinity)
    );
  return true;
}
const validateFrame = (value: unknown) => matchesShape(value, schema as Shape);
const fullMatch = (pattern: RegExp, value: string) =>
  pattern.exec(value)?.[0] === value;

export function normalizeVideoPage(input: unknown): string | null {
  if (
    typeof input !== 'string' ||
    !input ||
    [...input].length > routes.max_raw_length ||
    /[\s\x00-\x20\x7f-\x9f\\]/.test(input) ||
    !input.startsWith('/') ||
    input.startsWith('//')
  )
    return null;
  const path = input.split(/[?#]/, 1)[0];
  if (
    /%|\/\//.test(path) ||
    path.split('/').some((p) => p === '.' || p === '..' || p.length > 128) ||
    /[^A-Za-z0-9_/-]/.test(path)
  )
    return null;
  const normalized = path.endsWith('/') ? path.slice(0, -1) : path;
  return normalized || null;
}
export function resolveVideoPage(input: unknown): VideoKey | null {
  const path = normalizeVideoPage(input);
  return path
    ? (routes.routes.find((r) => fullMatch(new RegExp(r.pattern), path))
        ?.video_key as VideoKey) || null
    : null;
}
export function normalizeVideoLanguage(input: unknown): string {
  if (typeof input !== 'string') return 'en';
  const tag = input
    .trim()
    .replace(/_/g, '-')
    .replace(/[A-Z]/g, (c) => c.toLowerCase());
  return tag.length <= 10 && fullMatch(/[a-z]{2,3}(?:-[a-z0-9]{2,8})*/, tag)
    ? tag
    : 'en';
}
export function resolveVideoLocale(
  input: unknown,
  acceptLanguage?: string | null,
): string {
  if (input == null && typeof acceptLanguage === 'string') {
    const candidates = acceptLanguage.split(',').flatMap((entry, index) => {
      const parts = entry.trim().split(';');
      const language = parts[0].trim().replace(/_/g, '-');
      if (
        parts.length > 2 ||
        !fullMatch(/[A-Za-z]{2,3}(?:-[A-Za-z0-9]{2,8})*/, language)
      )
        return [];
      const quality =
        parts.length === 1
          ? '1'
          : fullMatch(/q=(0(?:\.\d{0,3})?|1(?:\.0{0,3})?)/, parts[1].trim())
            ? parts[1].trim().slice(2)
            : '0';
      return Number(quality) > 0
        ? [{ language, quality: Number(quality), index }]
        : [];
    });
    candidates.sort((a, b) => b.quality - a.quality || a.index - b.index);
    input = candidates[0]?.language;
  }
  const normalized =
    typeof input === 'string'
      ? input
          .trim()
          .replace(/_/g, '-')
          .replace(/[A-Z]/g, (c) => c.toLowerCase())
      : '';
  const tag = fullMatch(/[a-z]{2,3}(?:-[a-z0-9]{2,8})*/, normalized)
    ? normalized
    : 'en';
  return routes.locales.includes(tag)
    ? tag
    : routes.locales.includes(tag.split('-')[0])
      ? tag.split('-')[0]
      : 'en';
}
export function isVideoAssetUrl(
  input: unknown,
  video?: Pick<PageVideo, 'video_key' | 'content_revision' | 'locale'>,
  extension?: string,
): input is string {
  if (
    typeof input !== 'string' ||
    input.length > 512 ||
    /[\x00-\x20\x7f-\uffff\\%?#]/.test(input) ||
    !input.startsWith(VIDEO_ORIGIN + '/')
  )
    return false;
  const pattern = new RegExp(
    '^' +
      VIDEO_ORIGIN.replace(/\./g, '\\.') +
      '/settings-assistant/(' +
      [...new Set(routes.routes.map((r) => r.video_key))].join('|') +
      ')/v([1-9][0-9]*)/(' +
      routes.locales.join('|') +
      ')\\.(mp4|vtt|png)$',
  );
  const match = pattern.exec(input);
  if (!match || match[0] !== input || !Number.isSafeInteger(Number(match[2])))
    return false;
  const parsed = new URL(input);
  return (
    parsed.origin === VIDEO_ORIGIN &&
    !parsed.username &&
    !parsed.password &&
    !parsed.port &&
    (!video ||
      (match[1] === video.video_key &&
        Number.isSafeInteger(video.content_revision) &&
        match[2] === String(video.content_revision) &&
        match[3] === video.locale)) &&
    (!extension || match[4] === extension)
  );
}
const plainText = (s: string, multiline = false) =>
  !/[<>]/.test(s) &&
  !/\p{C}/u.test(multiline ? s.replace(/\n/g, '') : s) &&
  !s.includes('-->') &&
  !!s.trim();

/** Validate again on hydration; catalog revisions deliberately do not restrict history. */
export function parsePageVideo(input: unknown): PageVideo | null {
  try {
    if (
      utf8Bytes(JSON.stringify(input)) > 65536 ||
      !validateFrame({
        type: 'page_video',
        video: input,
        trace_id: 'T',
        docbits_trace_id: 'T',
      })
    )
      return null;
    const v = input as PageVideo;
    const fallback = routes.english_audio_locales.includes(v.locale);
    if (
      v.visual_locale !== v.locale ||
      v.caption_locale !== v.locale ||
      v.audio_locale !== (fallback ? 'en' : v.locale) ||
      v.audio_mode !== (fallback ? 'english_fallback' : 'localized') ||
      !plainText(v.title) ||
      !plainText(v.transcript, true)
    )
      return null;
    for (const [slot, ext, mime, limit] of [
      ['mp4', 'mp4', 'video/mp4', 10000000],
      ['vtt', 'vtt', 'text/vtt; charset=utf-8', 32768],
      ['poster', 'png', 'image/png', 1000000],
    ] as const) {
      const a = v.assets[slot];
      if (!isVideoAssetUrl(a.url, v, ext) || a.mime !== mime || a.bytes > limit)
        return null;
    }
    let end = 0;
    let captionBytes = 0;
    const ids = new Set<string>();
    const segments = new Set<string>();
    let segment = '';
    for (const cue of v.captions) {
      if (
        !plainText(cue.text, true) ||
        cue.text.split('\n').some((line) => !line.trim()) ||
        cue.start_ms < end ||
        cue.start_ms >= cue.end_ms ||
        cue.end_ms > v.duration_ms ||
        ids.has(cue.cue_id)
      )
        return null;
      if (cue.segment_id !== segment) {
        if (segments.has(cue.segment_id)) return null;
        segments.add(cue.segment_id);
        segment = cue.segment_id;
      }
      ids.add(cue.cue_id);
      end = cue.end_ms;
      captionBytes += utf8Bytes(cue.text);
    }
    if (
      captionBytes > 24576 ||
      utf8Bytes(v.transcript) > 24576 ||
      v.transcript !==
        v.captions
          .map((c) => c.text)
          .join(' ')
          .replace(/\s+/g, ' ')
          .trim()
    )
      return null;
    const asset = (a: VideoAsset): VideoAsset => ({
      url: a.url,
      sha256: a.sha256,
      bytes: a.bytes,
      mime: a.mime,
    });
    return {
      schema_version: 1,
      video_key: v.video_key,
      content_revision: v.content_revision,
      locale: v.locale,
      title: v.title,
      visual_locale: v.visual_locale,
      audio_locale: v.audio_locale,
      caption_locale: v.caption_locale,
      audio_mode: v.audio_mode,
      duration_ms: v.duration_ms,
      width: v.width,
      height: v.height,
      fps: v.fps,
      assets: {
        mp4: asset(v.assets.mp4),
        vtt: asset(v.assets.vtt),
        poster: asset(v.assets.poster),
      },
      captions: v.captions.map((c) => ({
        segment_id: c.segment_id,
        cue_id: c.cue_id,
        start_ms: c.start_ms,
        end_ms: c.end_ms,
        text: c.text,
      })),
      transcript: v.transcript,
    };
  } catch {
    return null;
  }
}
export function parsePageVideoFrame(input: unknown): {
  type: 'page_video';
  video: PageVideo;
  trace_id: string;
  docbits_trace_id: string;
} | null {
  try {
    if (
      utf8Bytes('data: ' + JSON.stringify(input) + '\n\n') > 65536 ||
      !validateFrame(input)
    )
      return null;
    const f = input as {
      video: unknown;
      trace_id: string;
      docbits_trace_id: string;
    };
    const video = parsePageVideo(f.video);
    return video &&
      f.trace_id === f.docbits_trace_id &&
      !/[\x00-\x20\x7f]/.test(f.trace_id)
      ? {
          type: 'page_video',
          video,
          trace_id: f.trace_id,
          docbits_trace_id: f.trace_id,
        }
      : null;
  } catch {
    return null;
  }
}
export function parseVideoRetry(input: unknown): VideoRetry | undefined {
  const v = input as VideoRetry;
  return v &&
    v.intent === 'page_video' &&
    typeof v.page === 'string' &&
    normalizeVideoPage(v.page) === v.page &&
    typeof v.locale === 'string' &&
    normalizeVideoLanguage(v.locale) === v.locale
    ? { page: v.page, locale: v.locale, intent: 'page_video' }
    : undefined;
}
export function hasPublishedVideo(
  path: string,
  published: Record<string, Record<string, string[]>> = catalog,
): boolean {
  const key = resolveVideoPage(path);
  return (
    !!key &&
    Object.entries(published[key] || {}).some(
      ([revision, locales]) =>
        fullMatch(/[1-9][0-9]*/, revision) &&
        Number.isSafeInteger(Number(revision)) &&
        Array.isArray(locales) &&
        locales.includes('en') &&
        locales.every((l) => routes.locales.includes(l)),
    )
  );
}
