export function videoVtt(video: PageVideo): string {
  const valid = parsePageVideo(video);
  if (!valid) throw new Error('Invalid page video');
  const time = (ms: number) =>
    `${String(Math.floor(ms / 3600000)).padStart(2, '0')}:${String(Math.floor(ms / 60000) % 60).padStart(2, '0')}:${String(Math.floor(ms / 1000) % 60).padStart(2, '0')}.${String(ms % 1000).padStart(3, '0')}`;
  return (
    'WEBVTT\n\n' +
    valid.captions
      .map(
        (c) =>
          `${c.cue_id}\n${time(c.start_ms)} --> ${time(c.end_ms)}\n${c.text.replace(/&/g, '&amp;')}\n\n`,
      )
      .join('')
  );
}
