<template>
  <div
    ref="container"
    class="assistant-chat__messages"
    :class="`${testId}__messages`"
  >
    <slot></slot>
  </div>
</template>

<script lang="ts">
import { defineComponent } from 'vue';

export default defineComponent({
  name: 'AssistantMessageList',

  props: {
    testId: {
      type: String,
      default: 'settings-assistant',
    },
  },

  methods: {
    scrollToBottom() {
      this.$nextTick(() => {
        const el = this.$refs.container as HTMLElement | undefined;
        if (el) el.scrollTop = el.scrollHeight;
      });
    },
  },
});
</script>

