/**
 * CORE-6108 — shared "make a readable message out of an error response
 * body" logic for both the chat SSE service and the CORE-6109 apply
 * service.
 *
 * FastAPI's default 422 validation-error body shapes `detail` as an ARRAY
 * of `{loc, msg, type}` objects, not a string. The naive
 * `String(body.message || body.detail || fallback)` both services used to
 * do calls `Array.prototype.toString()` on that array — which joins each
 * element via its own (default `Object.prototype`) `toString()` — producing
 * the literal string `"[object Object],[object Object]"` in a toast or
 * dialog a real user sees.
 */
export function messageFromErrorBody(
  body: Record<string, unknown>,
  fallback: string,
): string {
  if (typeof body.message === 'string' && body.message) return body.message;
  if (typeof body.detail === 'string' && body.detail) return body.detail;
  if (Array.isArray(body.detail)) {
    const messages = body.detail
      .map((entry) => {
        if (!entry || typeof entry !== 'object') return null;
        const msg = (entry as Record<string, unknown>).msg;
        return typeof msg === 'string' && msg ? msg : null;
      })
      .filter((m): m is string => !!m);
    if (messages.length) return messages.join('; ');
  }
  return fallback;
}
