<template>
  <div
    class="assistant-chat__applied-change"
    :class="{ 'assistant-chat__applied-change--failed': failed }"
    :data-test="`${testId}-applied-change`"
  >
    <Icon
      :icon="failed ? 'mdi:alert-circle-outline' : 'mdi:check-circle-outline'"
      width="16"
      height="16"
      class="shrink-0"
      :class="failed ? 'text-destructive' : 'text-success'"
    />
    <span class="assistant-chat__applied-change-text">{{ content }}</span>
    <template v-if="undone">
      <span
        class="assistant-chat__applied-change-undone"
        :data-test="`${testId}-applied-change-undone`"
        >{{ undoneLabel || $t('settings_assistant_apply_undo_success') }}</span
      >
    </template>
    <template v-else-if="!expired">
      <span
        class="assistant-chat__applied-change-expiry"
        :data-test="`${testId}-applied-change-expiry`"
        >{{ remainingLabel }}</span
      >
      <slot name="action"></slot>
    </template>
  </div>
</template>

<script lang="ts">
import { defineComponent, type PropType } from 'vue';
import { Icon } from '@iconify/vue';

export default defineComponent({
  name: 'AssistantAppliedChangeLine',

  components: { Icon },

  props: {
    content: {
      type: String,
      required: true,
    },
    undone: {
      type: Boolean,
      default: false,
    },
    // Epoch ms; without it the undo offer never expires.
    expiresAt: {
      type: Number as PropType<number | null>,
      default: null,
    },
    nowMs: {
      type: Number,
      default: () => Date.now(),
    },
    failed: {
      type: Boolean,
      default: false,
    },
    undoneLabel: {
      type: String,
      default: '',
    },
    testId: {
      type: String,
      default: 'settings-assistant',
    },
  },

  computed: {
    expired(): boolean {
      return typeof this.expiresAt === 'number' && this.nowMs >= this.expiresAt;
    },
    // Whole minutes, floored so it never rounds up past the real expiry.
    remainingLabel(): string {
      if (typeof this.expiresAt !== 'number') return '';
      const minutes = Math.max(0, Math.floor((this.expiresAt - this.nowMs) / 60_000));
      return String(this.$t('settings_assistant_undo_expires_in', { minutes }));
    },
  },
});
</script>

<style lang="scss" scoped>
.assistant-chat__applied-change {
  display: flex;
  align-items: center;
  flex-wrap: wrap;
  gap: 8px;
  font-size: 13px;
}

.assistant-chat__applied-change-text {
  flex: 1 1 auto;
  min-width: 0;
}

.assistant-chat__applied-change-expiry,
.assistant-chat__applied-change-undone {
  font-size: 12px;
  color: var(--muted-foreground);
  white-space: nowrap;
}
</style>
