/**
 * CORE-6145 — the `settings_actions` chunk of the Settings Assistant stream: a
 * change the admin ASKED for (document types on/off, renaming an access group, creating an inactive
 * validation rule from the curated catalog (CORE-6243)),
 * already previewed by doc2-api against the org's real data. The model only
 * proposes it; nothing changes until the admin clicks "Yes" on the card.
 *
 * A payload is only rendered when each item carries what the card and the
 * confirm call need; anything else is dropped, never half-drawn.
 */
export type SettingsActionKind =
  | 'doc_type_activation'
  | 'group_rename'
  | 'lookup_field_search'
  | 'field_delete'
  | 'custom_validation_rule_create'
  | 'structured_output_for_supplier';

export interface SettingsActionChange {
  key: string;
  title: string;
  /** Active state or name; null means the structured-output setting is unset. */
  before: boolean | string | null;
  after: boolean | string | null;
}

export interface SettingsActionOffer {
  preview_id: string;
  kind: SettingsActionKind;
  changes: SettingsActionChange[];
  reversible: boolean;
  /** What the server previewed; sent again when the 5-minute preview expired. */
  params: Record<string, unknown>;
}

const KINDS: SettingsActionKind[] = [
  'doc_type_activation',
  'group_rename',
  'lookup_field_search',
  'field_delete',
  'custom_validation_rule_create',
  'structured_output_for_supplier',
];

function toChangeValue(
  value: unknown,
): SettingsActionChange['before'] | undefined {
  if (typeof value === 'boolean' || typeof value === 'string') return value;
  if (!value || typeof value !== 'object' || Array.isArray(value))
    return undefined;
  // Structured-output previews wrap the effective value with its source.
  // The card displays the value only; legacy offers already contain scalars.
  const v = value as Record<string, unknown>;
  if (typeof v.source !== 'string') return undefined;
  const inner: unknown = v.value;
  if (inner === null) return null;
  if (typeof inner === 'boolean' || typeof inner === 'string') return inner;
  return undefined;
}

function toChange(value: unknown): SettingsActionChange | null {
  if (!value || typeof value !== 'object') return null;
  const v = value as Record<string, unknown>;
  const before = toChangeValue(v.before);
  const after = toChangeValue(v.after);
  if (before === undefined || after === undefined) return null;
  return {
    key: typeof v.key === 'string' ? v.key : '',
    title: typeof v.title === 'string' ? v.title : '',
    before,
    after,
  };
}

/** One validated offer, or null. Also used for a fresh preview response. */
export function toSettingsActionOffer(
  value: unknown,
  fallbackParams: Record<string, unknown> = {},
): SettingsActionOffer | null {
  if (!value || typeof value !== 'object') return null;
  const v = value as Record<string, unknown>;
  if (typeof v.preview_id !== 'string' || !v.preview_id) return null;
  if (!KINDS.includes(v.kind as SettingsActionKind)) return null;
  if (!Array.isArray(v.changes)) return null;
  const changes = v.changes
    .map(toChange)
    .filter((c): c is SettingsActionChange => c !== null);
  if (!changes.length) return null;
  const params =
    v.params && typeof v.params === 'object' && !Array.isArray(v.params)
      ? (v.params as Record<string, unknown>)
      : fallbackParams;
  return {
    preview_id: v.preview_id,
    kind: v.kind as SettingsActionKind,
    changes,
    reversible: v.reversible !== false,
    params,
  };
}

/** The valid offers of a chunk's `items`; `[]` for anything that is not a list. */
export function parseSettingsActionOffers(
  items: unknown,
): SettingsActionOffer[] {
  if (!Array.isArray(items)) return [];
  return items
    .map((item) => toSettingsActionOffer(item))
    .filter((o): o is SettingsActionOffer => o !== null);
}
