<template>
  <div class="assistant-chat__example-chips">
    <button
      v-for="item in items"
      :key="item.key"
      type="button"
      class="assistant-chat__example-chip"
      :class="
        item.primary
          ? ['assistant-chat__example-chip--primary', `${testId}__example-chip--primary`]
          : []
      "
      :data-test="item.dataTest || `${testId}-example-chip`"
      :disabled="disabled || item.disabled || undefined"
      @click="$emit('pick', item)"
    >
      {{ item.label }}
    </button>
  </div>
</template>

<script lang="ts">
import { defineComponent, type PropType } from 'vue';

export interface AssistantExampleChip {
  key: string;
  label: string;
  primary?: boolean;
  dataTest?: string;
  disabled?: boolean;
}

export default defineComponent({
  name: 'AssistantExampleChips',

  props: {
    items: {
      type: Array as PropType<AssistantExampleChip[]>,
      required: true,
    },
    disabled: {
      type: Boolean,
      default: false,
    },
    testId: {
      type: String,
      default: 'settings-assistant',
    },
  },

  emits: ['pick'],
});
</script>

<style lang="scss" scoped>
.assistant-chat__example-chips {
  display: flex;
  flex-direction: column;
  align-items: stretch;
  gap: 6px;
}

.assistant-chat__example-chip {
  padding: 8px 12px;
  border-radius: 10px;
  border: 1px solid var(--border);
  background: var(--card);
  color: var(--foreground);
  font-size: 13px;
  line-height: 1.35;
  cursor: pointer;
  text-align: left;
  transition: border-color 0.15s ease, background-color 0.15s ease;

  &:hover:not(:disabled) {
    border-color: var(--primary);
    background: color-mix(in srgb, var(--primary) 6%, transparent);
  }

  &:disabled {
    opacity: 0.5;
    cursor: default;
  }

  &:focus-visible {
    outline: 2px solid var(--ring);
    outline-offset: 2px;
  }
}

// A page's primary action: the one filled chip among the outlined ones.
.assistant-chat__example-chip--primary {
  border-color: var(--primary);
  background: var(--primary);
  color: var(--primary-foreground);
  font-weight: 600;

  &:hover:not(:disabled) {
    background: color-mix(in srgb, var(--primary) 88%, var(--foreground));
  }
}
</style>
