<template>
  <aside
    ref="panelEl"
    class="assistant-chat bg-card border-l border-border"
    :class="testId"
    :data-test="`${testId}-panel`"
    :role="overlay ? 'dialog' : 'complementary'"
    :aria-modal="overlay ? 'true' : undefined"
    :aria-label="ariaLabel"
    :style="!overlay && width ? { flexBasis: width + 'px' } : undefined"
    @keydown.tab="onPanelTabKeydown"
  >
    <slot name="grip"></slot>
    <slot name="header"></slot>
    <slot></slot>
    <slot name="footer"></slot>
  </aside>
</template>

<script lang="ts">
import { defineComponent } from 'vue';

const FOCUSABLE_SELECTOR =
  'a[href], button:not([disabled]), input:not([disabled]), textarea:not([disabled]), select:not([disabled]), [tabindex]:not([tabindex="-1"])';

export default defineComponent({
  name: 'AssistantShell',

  props: {
    overlay: {
      type: Boolean,
      default: false,
    },
    width: {
      type: Number as () => number | null,
      default: null,
    },
    ariaLabel: {
      type: String,
      default: '',
    },
    testId: {
      type: String,
      default: 'settings-assistant',
    },
  },

  methods: {
    // Focus trap while the panel is a modal overlay.
    onPanelTabKeydown(event: KeyboardEvent) {
      if (!this.overlay) return;
      const root = this.$refs.panelEl as HTMLElement | undefined;
      if (!root) return;
      const focusable = Array.from(
        root.querySelectorAll<HTMLElement>(FOCUSABLE_SELECTOR),
      ).filter((el) => el.offsetParent !== null);
      if (!focusable.length) return;
      const first = focusable[0];
      const last = focusable[focusable.length - 1];
      const active = document.activeElement;
      if (event.shiftKey && active === first) {
        event.preventDefault();
        last.focus();
      } else if (!event.shiftKey && active === last) {
        event.preventDefault();
        first.focus();
      }
    },
  },
});
</script>

<style lang="scss" scoped>
.assistant-chat {
  display: flex;
  flex-direction: column;
  height: 100%;
  min-width: 0;
  /* CORE-6161: without this the column cannot shrink below its content, so the
     message list grows and pushes the header/footer out instead of scrolling. */
  min-height: 0;
  position: relative; // anchors the resize grip
}
</style>
