<template>
  <AssistantActionCard
    :kicker="kicker"
    :title="title"
    test-id="settings-assistant-settings-action"
    data-test="settings-assistant-settings-action"
    :data-kind="current.kind"
  >
    <template #actions>
      <ul
        class="sa-action-card__changes text-sm"
        data-test="settings-assistant-settings-action-changes"
      >
        <li
          v-for="change in shownChanges"
          :key="change.key || change.title"
          data-test="settings-assistant-settings-action-change"
        >
          <template v-if="current.kind === 'group_rename'">
            <span class="sa-action-card__before">{{ change.before }}</span>
            <span aria-hidden="true"> → </span>
            <strong>{{ change.after }}</strong>
          </template>
          <template v-else>
            <span>{{ change.title }}:</span>
            <span class="sa-action-card__before">{{
              stateLabel(change.before)
            }}</span>
            <span aria-hidden="true"> → </span>
            <strong>{{ stateLabel(change.after) }}</strong>
          </template>
        </li>
        <li v-if="hiddenCount" class="sa-action-card__more">
          {{ $t('settings_assistant_action_more', { count: hiddenCount }) }}
        </li>
      </ul>

      <!-- CORE-6243: the rule is created INACTIVE; say who switches it on. -->
      <p
        v-if="current.kind === 'custom_validation_rule_create'"
        class="text-sm"
        data-test="settings-assistant-settings-action-rule-note"
      >
        {{ $t('settings_assistant_action_rule_note') }}
      </p>

      <p
        v-if="noticeKey"
        class="text-sm"
        role="status"
        data-test="settings-assistant-settings-action-notice"
      >
        {{ $t(noticeKey) }}
      </p>

      <!-- Done: say so, offer undo while it is possible. -->
      <div
        v-if="state === 'done'"
        class="sa-action-card__row"
        role="status"
        data-test="settings-assistant-settings-action-done"
      >
        <span>{{ $t('settings_assistant_action_done') }}</span>
        <q-btn
          v-if="undoId"
          flat
          dense
          no-caps
          :disable="busy"
          :label="$t('settings_assistant_action_undo')"
          data-test="settings-assistant-settings-action-undo"
          @click="undoAction"
        />
      </div>

      <!-- The admin's own click on "Yes" is the only thing that writes. -->
      <div v-else-if="state === 'offered'" class="sa-action-card__row">
        <q-btn
          unelevated
          no-caps
          color="primary"
          :disable="busy"
          :loading="busy"
          :label="$t('settings_assistant_action_yes')"
          data-test="settings-assistant-settings-action-yes"
          @click="confirmAction"
        />
        <q-btn
          flat
          no-caps
          :disable="busy"
          :label="$t('settings_assistant_action_cancel')"
          data-test="settings-assistant-settings-action-cancel"
          @click="state = 'cancelled'"
        />
      </div>

      <p
        v-else-if="state === 'cancelled'"
        class="text-sm"
        data-test="settings-assistant-settings-action-cancelled"
      >
        {{ $t('settings_assistant_action_cancelled') }}
      </p>

      <p
        v-else-if="state === 'undone'"
        class="text-sm"
        data-test="settings-assistant-settings-action-undone"
      >
        {{ $t('settings_assistant_action_undone') }}
      </p>

      <p
        v-if="errorKey"
        class="sa-action-card__error text-sm"
        role="alert"
        data-test="settings-assistant-settings-action-error"
      >
        {{ $t(errorKey) }}
      </p>
    </template>
  </AssistantActionCard>
</template>

<script lang="ts">
import { defineComponent, type PropType } from 'vue';
import AssistantActionCard from 'src/components/AssistantChat/AssistantActionCard.vue';
import { ApplyRequestError } from 'src/services/settingsAssistant/settingsAssistantApplyService';
import { settingsAssistantSettingsActionService } from 'src/services/settingsAssistant/settingsAssistantSettingsActionService';
import {
  toSettingsActionOffer,
  type SettingsActionOffer,
} from 'src/utils/settingsAssistant/settingsActionOffers';
import { getOrgId } from 'src/utils/organization/org_id_helper';
import { logger } from 'src/utils/logger';

type CardState = 'offered' | 'done' | 'cancelled' | 'undone' | 'closed';

const MAX_SHOWN = 8;

/**
 * CORE-6145 — a settings change the admin asked the assistant for, prepared by
 * the server (preview) and shown with its real before / after. "Yes" carries it
 * out, "Undo" restores the previous state for 15 minutes. When the 5-minute
 * preview has expired, the card previews again and shows the fresh result for a
 * second "Yes" — it never writes anything the admin has not seen.
 */
export default defineComponent({
  name: 'SettingsAssistantSettingsActionCard',

  components: { AssistantActionCard },

  props: {
    offer: { type: Object as PropType<SettingsActionOffer>, required: true },
  },

  emits: ['changed'],

  data() {
    return {
      current: this.offer as SettingsActionOffer,
      state: 'offered' as CardState,
      undoId: null as string | null,
      busy: false,
      errorKey: '',
      noticeKey: '',
    };
  },

  computed: {
    kicker(): string {
      if (this.current.kind === 'lookup_field_search') {
        return this.$t('settings_assistant_action_lookup_kicker');
      }
      if (this.current.kind === 'field_delete') {
        return this.$t('settings_assistant_action_field_kicker');
      }
      if (this.current.kind === 'custom_validation_rule_create') {
        return this.$t('settings_assistant_action_rule_kicker');
      }
      if (this.current.kind === 'structured_output_for_supplier') {
        return this.$t('settings_assistant_action_structured_output_kicker');
      }
      return this.$t(
        this.current.kind === 'group_rename' ? 'groups' : 'document_types',
      );
    },
    title(): string {
      if (this.current.kind === 'group_rename') {
        return this.$t('settings_assistant_action_group_rename');
      }
      if (this.current.kind === 'field_delete') {
        // CORE-6145: "lösch das test_hidden feld"
        return this.$t('settings_assistant_action_field_delete', {
          field: this.current.changes[0]?.title || '',
        });
      }
      if (this.current.kind === 'custom_validation_rule_create') {
        return this.$t('settings_assistant_action_rule_create');
      }
      if (this.current.kind === 'structured_output_for_supplier') {
        // CORE-6454: the change title is the supplier
        return this.$t('settings_assistant_action_structured_output', {
          supplier: this.current.changes[0]?.title || '',
        });
      }
      if (this.current.kind === 'lookup_field_search') {
        // CORE-6145: "search by the VAT id automatically from now on"
        return this.$t('settings_assistant_action_lookup_search', {
          field:
            this.current.changes[0]?.title ||
            String(this.current.params?.title || ''),
        });
      }
      const count = this.current.changes.length;
      const on = this.current.changes[0]?.after === true;
      return this.$t(
        on
          ? 'settings_assistant_action_doc_types_on'
          : 'settings_assistant_action_doc_types_off',
        { count },
      );
    },
    shownChanges(): SettingsActionOffer['changes'] {
      return this.current.changes.slice(0, MAX_SHOWN);
    },
    hiddenCount(): number {
      return Math.max(0, this.current.changes.length - MAX_SHOWN);
    },
  },

  methods: {
    stateLabel(value: boolean | string | null): string {
      if (value === null) {
        return this.$t('settings_assistant_apply_value_unset');
      }
      if (this.current.kind === 'field_delete') {
        return this.$t(
          value === true
            ? 'settings_assistant_action_field_present'
            : 'settings_assistant_action_field_deleted',
        );
      }
      if (this.current.kind === 'custom_validation_rule_create') {
        return this.$t(
          value === true
            ? 'settings_assistant_action_rule_inactive'
            : 'settings_assistant_action_rule_absent',
        );
      }
      if (this.current.kind === 'lookup_field_search') {
        return this.$t(
          value === true
            ? 'settings_assistant_action_lookup_auto'
            : 'settings_assistant_action_lookup_manual',
        );
      }
      return this.$t(
        value === true
          ? 'settings_assistant_action_on'
          : 'settings_assistant_action_off',
      );
    },

    /** Only status / error code are logged (customer data stays out). */
    failureKey(err: unknown): string {
      const e = err as ApplyRequestError;
      if (e?.errorCode === 'SETTINGS_ACTION_RULE_ALREADY_CHECKED') {
        return 'settings_assistant_action_rule_exists';
      }
      if (err instanceof ApplyRequestError && e.status === 409) {
        return 'settings_assistant_action_error_stale';
      }
      logger.error('[SettingsAssistantSettingsActionCard]', 'action failed', {
        status: e?.status,
        errorCode: e?.errorCode,
      });
      return 'settings_assistant_action_error';
    },

    /** The preview expired (or the page was reloaded): preview again and ask
     * again. Already in that state -> nothing left to do. */
    async refreshPreview(orgId: string) {
      try {
        const fresh = toSettingsActionOffer(
          await settingsAssistantSettingsActionService.preview(
            this.current.kind,
            this.current.params,
          ),
          this.current.params,
        );
        if (orgId !== getOrgId()) return;
        if (!fresh) throw new Error('invalid preview');
        this.current = fresh;
        this.noticeKey = 'settings_assistant_action_refreshed';
      } catch (err) {
        if (orgId !== getOrgId()) return;
        if (
          err instanceof ApplyRequestError &&
          err.errorCode === 'SETTINGS_ACTION_NOTHING_TO_DO'
        ) {
          this.state = 'closed';
          this.noticeKey = 'settings_assistant_action_nothing_to_do';
          return;
        }
        this.errorKey = this.failureKey(err);
      }
    },

    async confirmAction() {
      if (this.busy || this.state !== 'offered') return;
      this.busy = true;
      this.errorKey = '';
      this.noticeKey = '';
      const orgId = getOrgId();
      try {
        const result = await settingsAssistantSettingsActionService.confirm(
          this.current.preview_id,
        );
        if (orgId !== getOrgId()) return;
        this.undoId = result.undo_id;
        this.state = 'done';
        this.$emit('changed', { kind: this.current.kind, action: 'confirm' });
      } catch (err) {
        if (orgId !== getOrgId()) return;
        if (err instanceof ApplyRequestError && err.status === 404) {
          await this.refreshPreview(orgId);
        } else {
          this.errorKey = this.failureKey(err);
        }
      } finally {
        this.busy = false;
      }
    },

    async undoAction() {
      const undoId = this.undoId;
      if (!undoId || this.busy) return;
      this.busy = true;
      this.errorKey = '';
      const orgId = getOrgId();
      try {
        await settingsAssistantSettingsActionService.undo(undoId);
        if (orgId !== getOrgId()) return;
        this.undoId = null;
        this.state = 'undone';
        this.$emit('changed', { kind: this.current.kind, action: 'undo' });
      } catch (err) {
        if (orgId !== getOrgId()) return;
        // The undo no longer applies (expired or changed again): drop it.
        this.undoId = null;
        this.errorKey = this.failureKey(err);
      } finally {
        this.busy = false;
      }
    },
  },
});
</script>

