/**
 * CORE-6103 — client for creating a transformation rule from the settings
 * assistant chat (doc2-api `POST /v3/settings-assistant/transformation-rules/
 * confirm|undo`, routers/settings_assistant_rules.py).
 *
 * The preview itself is NOT requested from here: the chat stream delivers it
 * as a `{type: 'rule_preview', rule_preview}` chunk (helpers/settings_assistant/
 * rule_chat.py), already dry-run on sample documents and stored server side
 * for 5 minutes under its `preview_token`. The browser only ever sends that
 * token back — confirm writes exactly the rule the server previewed, never
 * anything the client supplies.
 *
 * Both routes are org-admin only and every rule created here is INACTIVE.
 *
 * The generated SDK does not have these routes yet (the API PR is not
 * merged), so this calls the generated client's own `request()` core with
 * the path spelled out — same auth, base URL, org header and ApiError
 * behaviour as every generated method. Once the SDK is regenerated this can
 * switch to the generated `SettingsAssistantTransformationRulesService`.
 */
import { OpenAPI } from 'src/generated-api-sdk/core/OpenAPI';
import { request as sdkRequest } from 'src/generated-api-sdk/core/request';
import { ApiError } from 'src/generated-api-sdk/core/ApiError';
import { getOrgId } from 'src/utils/organization/org_id_helper';
import { messageFromErrorBody } from 'src/utils/settingsAssistant/apiErrorMessage';
import { TRACE_BODY_FIELD } from 'src/utils/errorTraceId';

export const RULES_BASE_PATH = '/v3/settings-assistant/transformation-rules';

export type RuleScope = 'header' | 'column' | 'table' | 'document';

/** One field/cell the rule targets on a sample document
 * (routers/transformation_rules/models.py `FieldTestResult`). */
export interface RuleDryRunFieldResult {
  location: string;
  matched: boolean;
  before?: unknown;
  after?: unknown;
}

/** A table-scope outcome (`TableTestResult`) — row counts, not values. */
export interface RuleDryRunTableResult {
  location: string;
  table_name?: string | null;
  matched: boolean;
  rows_before: number;
  rows_after: number;
  rows_added: number;
  rows_removed: number;
  clears_po_match?: boolean;
}

export interface RuleDryRunDocument {
  document_id: string;
  filename?: string | null;
  created_on?: string | null;
  matched: boolean;
  changed: boolean;
  results: RuleDryRunFieldResult[];
  results_total?: number;
  table_results: RuleDryRunTableResult[];
  error?: string | null;
}

export interface RuleDryRun {
  documents: RuleDryRunDocument[];
  summary: { tested: number; matched: number; changed: number; failed: number };
}

export interface RulePreviewWarning {
  code: string;
  severity: 'info' | 'warning' | string;
  params?: Record<string, unknown>;
  /** Already translated by the server (Accept-Language / chat language). */
  message: string;
}

/** The normalised rule the server stored with the preview. */
export interface RulePreviewRule {
  doc_type: string;
  scope: RuleScope;
  rule_key: string;
  display_name: string;
  description?: string | null;
  target_field: string;
  source?: string | null;
  table_name?: string | null;
  is_active: boolean;
  [key: string]: unknown;
}

/** The `rule_preview` chunk payload (apply_rules.preview_rule_creation). */
export interface RulePreview {
  preview_id: string;
  preview_token: string;
  doc_type: string;
  rule: RulePreviewRule;
  /** Readable one-sentence summary, in the chat language. */
  sentence: string;
  scope: RuleScope;
  will_be_inactive: boolean;
  created_via?: string;
  /** False when TRANSFORMATION_RULES_ENABLED is off for the doc type. */
  activation_enabled: boolean;
  dry_run: RuleDryRun;
  warnings: RulePreviewWarning[];
  /** ISO timestamp — the preview token is refused after this. */
  expires_at: string;
  expires_in_seconds: number;
}

export interface RuleConfirmResult {
  applied: boolean;
  verified: boolean;
  rule_id: string;
  rule_key: string;
  doc_type: string;
  display_name: string;
  is_active: boolean;
  created_on?: string | null;
  /** Pass this to undo(). `undo_id` is the same value. */
  operation_id: string;
  undo_id: string;
  /** ISO timestamp — end of the 15-minute undo window. */
  expires_at: string;
  expires_in_seconds: number;
}

export interface RuleUndoResult {
  applied: boolean;
  verified: boolean;
  undone: boolean;
  rule_id: string;
  rule_key?: string;
  doc_type?: string;
}

/** A failed confirm/undo, with the HTTP status and doc2-api's `error_code`
 * so the card can show a specific text per case (403/404/409/410/429/503). */
export class RuleRequestError extends Error {
  status?: number;
  errorCode?: string;
  traceId: string;

  constructor(message: string, status?: number, errorCode?: string, traceId = '') {
    super(message);
    this.name = 'RuleRequestError';
    this.status = status;
    this.errorCode = errorCode;
    this.traceId = traceId;
  }
}

function toRuleRequestError(error: unknown): RuleRequestError {
  if (error instanceof ApiError) {
    const body = (error.body ?? {}) as Record<string, unknown>;
    return new RuleRequestError(
      messageFromErrorBody(body, `HTTP ${error.status}`),
      error.status,
      typeof body.error_code === 'string' ? body.error_code : undefined,
      String(body[TRACE_BODY_FIELD] || ''),
    );
  }
  return new RuleRequestError(error instanceof Error ? error.message : String(error));
}

async function post<T>(path: string, body: Record<string, unknown>): Promise<T> {
  try {
    return (await sdkRequest(OpenAPI, {
      method: 'POST',
      url: `${RULES_BASE_PATH}${path}`,
      headers: { 'X-ORG-ID': getOrgId() },
      body,
      mediaType: 'application/json',
    })) as T;
  } catch (error) {
    throw toRuleRequestError(error);
  }
}

/** A chunk payload is only rendered as a card when it carries what the card
 * and the confirm call need — anything else is ignored, never half-drawn. */
export function isRulePreview(value: unknown): value is RulePreview {
  if (!value || typeof value !== 'object') return false;
  const v = value as Partial<RulePreview>;
  return (
    typeof v.preview_token === 'string' &&
    !!v.preview_token &&
    typeof v.sentence === 'string' &&
    !!v.rule &&
    typeof v.rule === 'object' &&
    !!v.dry_run &&
    typeof v.dry_run === 'object' &&
    Array.isArray(v.dry_run.documents)
  );
}

export const settingsAssistantRuleService = {
  /** Creates the previewed rule (always inactive). Only ever call this as
   * the direct result of the admin's own click on "Regel anlegen". */
  confirm(previewToken: string): Promise<RuleConfirmResult> {
    return post<RuleConfirmResult>('/confirm', { preview_token: previewToken });
  },

  /** Soft-deletes a rule created here — within 15 minutes and only while
   * nobody has changed or activated it since (409 otherwise). */
  undo(operationId: string): Promise<RuleUndoResult> {
    return post<RuleUndoResult>('/undo', { operation_id: operationId });
  },
};

export default settingsAssistantRuleService;
