    class="sa-rule-card"
    data-test="settings-assistant-rule-preview"
  >
    <div class="sa-rule-card__head">
      <span class="sa-rule-card__kicker">{{
        $t('settings_assistant_rule_preview_title')
      }}</span>
      <span
        class="sa-rule-card__scope"
        :class="`sa-rule-card__scope--${preview.scope}`"
        data-test="settings-assistant-rule-scope"
        >{{ $t(scopeLabelKey) }}</span
      >
    </div>

    <p class="font-semibold" data-test="settings-assistant-rule-name">
      {{ preview.rule.display_name }}
    </p>
    <p class="text-sm" data-test="settings-assistant-rule-sentence">
      {{ preview.sentence }}
    </p>
    <p
      v-if="targetText"
      class="text-xs text-muted-foreground"
      data-test="settings-assistant-rule-target"
    >
      {{ targetText }}
    </p>

    <!-- Dry run: one row per sample document, before → after per value. -->
    <div class="sa-rule-card__dry-run" data-test="settings-assistant-rule-dry-run">
      <p class="sa-rule-card__summary" data-test="settings-assistant-rule-summary">
        <Icon icon="mdi:flask-outline" width="14" height="14" class="shrink-0" />
        <span>{{ summaryText }}</span>
      </p>
      <ul v-if="preview.dry_run.documents.length" class="sa-rule-card__docs">
        <li
          v-for="doc in preview.dry_run.documents"
          :key="doc.document_id"
          class="sa-rule-card__doc"
          data-test="settings-assistant-rule-doc"
        >
          <div class="sa-rule-card__doc-head">
            <span class="sa-rule-card__doc-name" :title="docName(doc)">{{
              docName(doc)
            }}</span>
            <span
              class="sa-rule-card__applies"
              :class="appliesClass(doc)"
              data-test="settings-assistant-rule-doc-applies"
              >{{ appliesLabel(doc) }}</span
            >
          </div>
          <template v-if="!doc.error">
            <div
              v-for="(res, rIdx) in matchedResults(doc)"
              :key="`r${rIdx}`"
              class="sa-rule-card__change"
              data-test="settings-assistant-rule-change"
            >
              <span class="sa-rule-card__location" :title="res.location">{{
                res.location
              }}</span>
              <span class="sa-rule-card__values">
                <span class="sa-rule-card__before">{{ formatValue(res.before) }}</span>
                <Icon icon="mdi:arrow-right" width="12" height="12" class="shrink-0" />
                <span class="sa-rule-card__after">{{ formatValue(res.after) }}</span>
              </span>
            </div>
            <div
              v-for="(tres, tIdx) in doc.table_results.filter((t) => t.matched)"
              :key="`t${tIdx}`"
              class="sa-rule-card__change"
              data-test="settings-assistant-rule-change"
            >
              <span class="sa-rule-card__location">{{
                tres.table_name || tres.location
              }}</span>
              <span class="sa-rule-card__values">{{
                $t('settings_assistant_rule_rows_change', {
                  before: tres.rows_before,
                  after: tres.rows_after,
                })
              }}</span>
            </div>
            <p
              v-if="hiddenResultCount(doc) > 0"
              class="text-xs text-muted-foreground"
            >
              {{
                $t('settings_assistant_rule_more_results', {
                  count: hiddenResultCount(doc),
                })
              }}
            </p>
          </template>
        </li>
      </ul>
    </div>

    <ul
      v-if="visibleWarnings.length"
      class="sa-rule-card__warnings"
      data-test="settings-assistant-rule-warnings"
    >
      <li
        v-for="w in visibleWarnings"
        :key="w.code"
        class="sa-rule-card__warning"
        :class="{ 'sa-rule-card__warning--strong': w.severity === 'warning' }"
        data-test="settings-assistant-rule-warning"
      >
        <Icon
          :icon="w.severity === 'warning' ? 'mdi:alert-outline' : 'mdi:information-outline'"
          width="14"
          height="14"
          class="shrink-0 mt-0.5"
        />
        <span>{{ w.message }}</span>
      </li>
    </ul>

    <p class="sa-rule-card__inactive-note" data-test="settings-assistant-rule-inactive-note">
      <Icon icon="mdi:power-plug-off-outline" width="14" height="14" class="shrink-0 mt-0.5" />
      <span>{{ $t('settings_assistant_rule_inactive_note') }}</span>
    </p>

    <div class="sa-rule-card__actions">
      <span
        v-if="createdRuleId"
        class="sa-rule-card__created"
        data-test="settings-assistant-rule-created-badge"
      >
        <Icon icon="mdi:check-circle-outline" width="14" height="14" />
        {{ $t('settings_assistant_rule_created_badge') }}
      </span>
      <p
        v-else-if="!canCreate"
        class="text-xs text-muted-foreground"
        data-test="settings-assistant-rule-admin-only"
      >
        {{ $t('settings_assistant_rule_admin_only') }}
      </p>
      <p
        v-else-if="previewExpired && !creating"
        class="text-xs text-muted-foreground"
        data-test="settings-assistant-rule-preview-expired"
      >
        {{ $t('settings_assistant_rule_preview_expired') }}
      </p>
