<script lang="ts">
import { defineComponent, type PropType } from 'vue';
import { Icon } from '@iconify/vue';
import settingsAssistantRuleService, {
  RuleRequestError,
  type RuleDryRunDocument,
  type RuleDryRunFieldResult,
  type RulePreview,
  type RulePreviewWarning,
} from 'src/services/settingsAssistant/settingsAssistantRuleService';
import { useSettingsAssistantConversationStore } from 'src/store/SettingsAssistant/settings_assistant_conversation.store';
import { useTrRulesSyncStore } from 'src/store/Settings/tr-rules-sync.store';
import { getOrgId } from 'src/utils/organization/org_id_helper';
import { canWriteOrgPreferences } from 'src/utils/preferences/canWriteOrgPreferences';

/** Same labels the rules list uses for its scope toggle (SCOPE_META in
 * transformation-rule-model.ts — not imported, to keep that 50 KB module out
 * of the assistant's chunk). */
const SCOPE_LABEL_KEYS: Record<string, string> = {
  header: 'scope_header',
  column: 'scope_column',
  table: 'scope_table',
  document: 'scope_routing',
};

const MAX_VALUE_LENGTH = 80;
const EXPIRY_TICK_MS = 5_000;

/** confirm() failure → the card's message. 404 and 410 both mean the
 * one-shot, 5-minute preview token is gone. */
export function confirmErrorKey(err: unknown): string {
  const status = err instanceof RuleRequestError ? err.status : undefined;
  switch (status) {
    case 403:
      return 'settings_assistant_rule_admin_only';
    case 404:
    case 410:
      return 'settings_assistant_rule_preview_expired';
    case 409:
      return 'settings_assistant_rule_error_stale';
    case 429:
      return 'settings_assistant_rule_error_rate_limited';
    case 503:
      return 'settings_assistant_rule_error_unavailable';
    default:
      return 'settings_assistant_rule_error_generic';
  }
}

export default defineComponent({
  name: 'SettingsAssistantRulePreviewCard',

  components: { Icon },

  props: {
    preview: {
      type: Object as PropType<RulePreview>,
      required: true,
    },
    /** Set once this preview's rule was created (the token is single-use). */
    createdRuleId: {
      type: String as PropType<string | null>,
      default: null,
    },
  },

  emits: ['created'],

  setup() {
    return {
      conversationStore: useSettingsAssistantConversationStore(),
      rulesSync: useTrRulesSyncStore(),
    };
  },

  data() {
    return {
      creating: false,
      errorKey: '' as string,
      errorDetail: '' as string,
      nowMs: Date.now(),
      tick: null as ReturnType<typeof setInterval> | null,
    };
  },

  computed: {
    scopeLabelKey(): string {
      return SCOPE_LABEL_KEYS[this.preview.scope] || 'scope_header';
    },

    canCreate(): boolean {
      return canWriteOrgPreferences();
    },

    previewExpired(): boolean {
      const expires = Date.parse(this.preview.expires_at || '');
      return Number.isFinite(expires) && this.nowMs >= expires;
    },

    targetText(): string {
      const rule = this.preview.rule;
      const field = rule.target_field || '';
      const table = rule.table_name || '';
      switch (this.preview.scope) {
        case 'column':
          return String(
            this.$t('settings_assistant_rule_target_column', { field, table }),
          );
        case 'table':
          return String(this.$t('settings_assistant_rule_target_table', { table }));
        case 'document':
          return String(this.$t('settings_assistant_rule_target_document', { field }));
        default:
          return field
            ? String(this.$t('settings_assistant_rule_target_header', { field }))
            : '';
      }
    },

    summaryText(): string {
      const summary = this.preview.dry_run.summary;
      if (!summary || !summary.tested) {
        return String(this.$t('settings_assistant_rule_dry_run_none'));
      }
      return String(
        this.$t('settings_assistant_rule_dry_run_summary', {
          matched: summary.matched,
          tested: summary.tested,
        }),
      );
    },

    /** The server's own "created inactive" warning is replaced by the
     * card's fixed, always-visible note — never shown twice. */
    visibleWarnings(): RulePreviewWarning[] {
      return (this.preview.warnings || []).filter(
        (w) => w && w.message && w.code !== 'inactive',
      );
    },
  },

  mounted() {
    if (!this.createdRuleId) {
      this.tick = setInterval(() => {
        this.nowMs = Date.now();
      }, EXPIRY_TICK_MS);
    }
  },

  beforeUnmount() {
    if (this.tick) clearInterval(this.tick);
  },

  methods: {
    docName(doc: RuleDryRunDocument): string {
      return doc.filename || doc.document_id.slice(0, 8);
    },

    appliesLabel(doc: RuleDryRunDocument): string {
      if (doc.error) return String(this.$t('settings_assistant_rule_dry_run_failed'));
      if (!doc.matched) return String(this.$t('settings_assistant_rule_applies_no'));
      if (!doc.changed) return String(this.$t('settings_assistant_rule_no_change'));
      return String(this.$t('settings_assistant_rule_applies_yes'));
    },

    appliesClass(doc: RuleDryRunDocument): string {
      if (doc.error) return 'sa-rule-card__applies--error';
      if (doc.matched) return 'sa-rule-card__applies--yes';
      return 'sa-rule-card__applies--no';
    },

    matchedResults(doc: RuleDryRunDocument): RuleDryRunFieldResult[] {
      return (doc.results || []).filter((r) => r.matched);
    },

    hiddenResultCount(doc: RuleDryRunDocument): number {
      const shown = (doc.results || []).length;
      return Math.max(0, (doc.results_total ?? shown) - shown);
    },

    formatValue(value: unknown): string {
      if (value === null || value === undefined || value === '') {
        return String(this.$t('settings_assistant_rule_empty_value'));
      }
      let text: string;
      if (typeof value === 'object') {
        try {
          text = JSON.stringify(value);
        } catch {
          text = String(value);
        }
      } else {
        text = String(value);
      }
      return text.length > MAX_VALUE_LENGTH
        ? `${text.slice(0, MAX_VALUE_LENGTH - 1)}…`
        : text;
    },

    async createRule() {
      if (this.creating || this.createdRuleId || !this.canCreate) return;
      this.creating = true;
      this.errorKey = '';
      this.errorDetail = '';
      const orgIdAtCreate = getOrgId();
      try {
        const result = await settingsAssistantRuleService.confirm(
          this.preview.preview_token,
        );
        if (!result.applied || !result.rule_id) {
          this.errorKey = 'settings_assistant_rule_error_generic';
          return;
        }
        this.conversationStore.recordRuleCreated({
          previewId: this.preview.preview_id,
          result,
          orgIdAtCreate,
          content: String(
            this.$t('settings_assistant_rule_created_entry', {
              name: result.display_name || this.preview.rule.display_name,
            }),
          ),
        });
        this.rulesSync.notifyChanged({
          docType: result.doc_type || this.preview.doc_type,
          ruleId: result.rule_id,
          kind: 'created',
        });
        if (this.tick) clearInterval(this.tick);
        this.tick = null;
        this.$emit('created', result);
      } catch (err) {
        this.errorKey = confirmErrorKey(err);
        // Only the generic case adds the server's own words — every known
        // status already has a specific, translated text.
        if (this.errorKey === 'settings_assistant_rule_error_generic') {
          this.errorDetail = err instanceof Error ? err.message : '';
        }
      } finally {
        this.creating = false;
      }
    },
  },
});
</script>

