import AssistantBubble from 'src/components/AssistantChat/AssistantBubble.vue';

export default defineComponent({
  name: 'AssistantStreamingBubble',

  components: { AssistantBubble, Icon },

  props: {
    text: {
      type: String,
      default: '',
