import { parsePageVideoFrame, utf8Bytes, type PageVideo } from 'src/utils/settingsAssistant/pageVideos';
/**
 * CORE-6108 — client for the settings assistant chat.
 *
 * The endpoint itself is CORE-6106 (doc2-api `POST /v3/settings-assistant/chat`,
 * Server-Sent Events). The browser only sends the conversation and the page it
 * is on, with the user's own bearer and organisation — the model runs server
 * side, so no model key and no model call ever lives in the frontend.
 *
 * Stream contract (one JSON object per `data:` line, `[DONE]` ends it):
 *   { type: 'text', delta }                      — answer text, appended
 *   { type: 'source', title, url, videos? }      — documentation link (+ explainer videos)
 *   { type: 'recommendation', recommendation }   — finding card
 *   { type: 'error', message, message_code?, docbits_trace_id? }
 *   { type: 'rule_preview', rule_preview }     — CORE-6103 drafted transformation
 *                                                rule (settingsAssistantRuleService.ts)
 * Every chunk may carry `docbits_trace_id`.
 */
import { getAuthorizationToken } from 'src/pages/APIs';
import { getOrgId } from 'src/utils/organization/org_id_helper';
import { TRACE_BODY_FIELD } from 'src/utils/errorTraceId';
import { messageFromErrorBody } from 'src/utils/settingsAssistant/apiErrorMessage';
// Direct file import, NOT the src/generated-api-sdk barrel (index.ts
// re-exports 124 generated service classes + 660+ models) — CLAUDE.md's
// barrel-import rule: a barrel import pulls the whole SDK into whatever
// chunk loads this service for the sake of one symbol.
import { OpenAPI } from 'src/generated-api-sdk/core/OpenAPI';

/**
 * DOCB-SDK-migration: the chat endpoint is Server-Sent Events —
 * openapi-typescript-codegen's axios-based client can't stream a response
 * body, so this keeps a raw `fetch()` for the body stream rather than
 * calling the generated `SettingsAssistantService.chatSettingsAssistantChatPost`
 * method directly. BASE comes from the generated SDK's own `OpenAPI.BASE`
 * (kept in sync app-wide by apiSdkService.ts's onApiBaseUrlChange) instead
 * of a hand-typed constant, so this can never drift from the same base URL
 * every other generated-SDK call uses.
 *
 * PATH is a local constant, not something openapi-typescript-codegen
 * exports separately — the generated method bakes its URL directly into
 * its own function body (see SettingsAssistantService.ts). It MUST match
 * that generated method's url exactly; settings-assistant-chat-path-contract
 * .unit.spec.ts is the guard — it calls the real generated method and
 * asserts the url it actually requests equals this constant, so a backend
 * rename or a stale regen shows up as a failing test here instead of the
 * silent 404 this migration exists to prevent (the web called
 * /v3/settings-assistant/chat while the API served /settings-assistant/chat).
 */
export const CHAT_PATH = '/settings-assistant/chat';

export type AssistantRole = 'user' | 'assistant';

export interface AssistantTurn {
  role: AssistantRole;
  content: string;
}

export interface AssistantSource {
  title: string;
  url: string;
  /** CORE-6111 — explainer videos of this docs page (validated, CDN mp4 only). */
  videos?: { title: string; url: string }[];
}

export interface AssistantImage {
  url: string;
  alt: string;
}

/**
 * CORE-6106's `recommendation` chunk contract (deep_links.py /
 * chat_guardrails.validate_recommendations): setting_key, scope, label_key,
 * breadcrumb[], app_path, anchor, doc_url, images[], current_value,
 * proposed_value, apply_tool (always null before CORE-6109).
 *
 * `title`/`reason`/`measured`/`id` are this panel's own additions on top of
 * that contract (the model's natural-language framing of the recommendation,
 * not part of the catalog). `deep_link` is kept as an alias of `app_path` —
 * the currently-deployed chat endpoint (PR #16800) emits both with the same
 * value as a compatibility shim; this panel prefers `app_path` and only
 * falls back to `deep_link` if a still-older server omits it.
 */
export interface AssistantRecommendation {
  id: string;
  title: string;
  /** Why this is recommended, with the measured value that triggered it. */
  reason: string;
  measured?: string;
  setting_key?: string;
  scope?: string;
  label_key?: string;
  /** Tolgee label keys of the real sidebar path, in breadcrumb order. */
  breadcrumb?: string[];
  doc_url?: string;
  /**
   * A relative app path (e.g. "/settings/modules/document-integration") the
   * panel can navigate to in-app. Validated client-side before it is ever
   * rendered — see SettingsAssistantPanel.resolveDeepLink.
   */
  app_path?: string;
  /** @deprecated alias of app_path — see the type-level note above. */
  deep_link?: string;
  /** data-test value of the exact control on that page, or null. */
  anchor?: string | null;
  /** A list of docs images, or catalog screenshots keyed by language. */
  images?: AssistantImage[] | Record<string, string | null>;
  current_value?: unknown;
  proposed_value?: unknown;
  /**
   * CORE-6109 — present once the recommended setting is in the Wave 1
   * apply catalog (deep_links.py, writable: true). Always "apply_setting"
   * when set, naming the MCP tool/apply flow the "Übernehmen" button uses;
   * null/absent means the setting cannot be applied yet and no button is
   * shown. See the doc2-api PR body for the full contract.
   */
  apply_tool?: string | null;
  preview_available?: boolean;
  /**
   * NOT part of the deployed contract yet (2026-09-29) — the catalog
   * (deep_links.py) doesn't send this field today. Accepted here
   * forward-compatibly for when it lands; `formatRecommendationValue`
   * (src/utils/settingsAssistant/formatRecommendationValue.ts) only
   * trusts it for boolean formatting (`=== 'bool'`), and otherwise falls
   * back to a value's own real JS type — never guesses "boolean" from a
   * string's contents alone.
   */
  value_type?: 'bool' | 'number' | 'enum' | string;
}

