// CORE-6161: what the user may see and do, sent first in each validation assistant stream.
export interface AssistantCapabilities {
  tier: 'viewer' | 'editor' | 'admin';
  can_change_fields: boolean;
  can_see_setup: boolean;
}

export type AssistantChunk =
  | { type: 'page_video'; video: PageVideo; trace_id: string; docbits_trace_id: string }
  | { type: 'outcome'; outcome: string; trace_id?: string; docbits_trace_id?: string }
  | {
      type: 'capabilities';
      capabilities: AssistantCapabilities;
      docbits_trace_id?: string;
      trace_id?: string;
    }
  | {
      type: 'action';
      action: AssistantActionPayload;
      docbits_trace_id?: string;
      trace_id?: string;
    }
  | {
      type: 'finding';
      finding: AssistantFindingPayload;
      docbits_trace_id?: string;
      trace_id?: string;
    }
  | {
      type: 'text';
      delta: string;
      message_code?: string;
      docbits_trace_id?: string;
      trace_id?: string;
    }
  | {
      type: 'source';
      title: string;
      url: string;
      videos?: unknown;
      docbits_trace_id?: string;
      trace_id?: string;
    }
  | {
      type: 'recommendation';
      recommendation: AssistantRecommendation;
      docbits_trace_id?: string;
      trace_id?: string;
    }
  | {
      type: 'error';
      message: string;
      message_code?: string;
      docbits_trace_id?: string;
      trace_id?: string;
    };

/** Read whichever trace-id field the server sent — CORE-6106's own chat
 * router emits `docbits_trace_id` (routers/settings_assistant.py's
 * `_sse_chunk`), but the documented contract calls it `trace_id`; accepting
 * either means neither naming keeps this panel's "copy trace id" broken. */
export function chunkTraceId(chunk: {
  docbits_trace_id?: string;
  trace_id?: string;
}): string {
  return chunk.trace_id || chunk.docbits_trace_id || '';
}

export interface AssistantRequest {
  page: string;
  messages: AssistantTurn[];
  /**
   * The normalized full UI locale, including pt-br. The
   * generated SDK's ChatRequest model already has a `language` field
   * (src/generated-api-sdk/models/ChatRequest.ts); this raw-fetch client
   * doesn't go through that generated method (see the class doc above) but
   * mirrors the same field so the assistant answers in the language the
   * user is actually looking at, not whatever the server defaults to.
   */
  language?: string;
  /**
   * The generated SDK's ChatRequest model also carries an optional
   * `conversation_id` — the server keys its own conversation history by it.
   * Generated once per conversation by the conversation store
   * (crypto.randomUUID()) and reset on "Neuer Chat".
   */
  conversation_id?: string;
  /**
   * CORE-6103 — a deterministic intent from a page chip (today only
   * "create_transformation_rule", from "Neue Regel anlegen" on
   * /settings/transformation-rules/:doc_type). doc2-api honours it only
   * together with a `page` that resolves to that page; omitted otherwise.
   */
  intent?: 'create_transformation_rule' | 'page_video';
}

export const TRACE_HEADER = 'x-docbits-trace-id';

/** The endpoint is not deployed yet (CORE-6106) — the panel shows its "being set up" state. */
export class AssistantUnavailableError extends Error {
  constructor() {
    super('settings assistant is not available yet');
    this.name = 'AssistantUnavailableError';
  }
}

/**
 * CORE-6108 review (Codex): no chunk arrived for
 * ASSISTANT_STREAM_INACTIVITY_TIMEOUT_MS — a stalled connection, not a
 * server-reported failure. Distinct from AssistantRequestError so the panel
 * can show a retryable, translated "the assistant is taking too long" state
 * rather than the generic error bubble.
 */
export class AssistantStreamTimeoutError extends Error {
  constructor() {
    super('settings assistant stream timed out');
    this.name = 'AssistantStreamTimeoutError';
  }
}

export const ASSISTANT_STREAM_INACTIVITY_TIMEOUT_MS = 30_000;

/**
 * CORE-6108 review (Codex): the 30s inactivity timeout above only covers the
 * BODY-reading phase — it doesn't start until `response.body` already
 * exists. A hang in getAuthorizationToken(), or a `fetch()` that never gets
 * as far as response headers (a stalled TCP connection, a proxy sitting on
 * the request), had no timeout at all before this and left the UI stuck on
 * "thinking" forever. This bounds that phase separately.
 */
export const ASSISTANT_HEADER_TIMEOUT_MS = 15_000;

/**
 * Settles like `work`, unless `signal` aborts first — then rejects with a
 * real `AbortError` (what an aborted `fetch()` throws; the panel's `runTurn`
 * swallows exactly that name as user-initiated cancellation). The abort
 * listener is removed as soon as either side settles, so a long-lived
 * signal never accumulates listeners across calls.
 *
 * Codex review (r1 + r2): used for `getAuthorizationToken()` so Stop cuts in
 * during the token phase too. That call deliberately gets NO signal of its
 * own: it goes through AbstractApiService.getToken() ->
 * useAuthTokenStore().setAuthToken(), the ONE app-wide token refresh every
 * other request in the app also waits on. Cancelling it because one chat
 * request was stopped would fail those unrelated callers, so Stop only
 * DETACHES this caller from the shared refresh — the refresh itself runs to
 * completion and still benefits everyone else.
 */
export function detachOnAbort<T>(
  work: Promise<T>,
  signal?: AbortSignal,
): Promise<T> {
  if (!signal) return work;
  if (signal.aborted) {
    return Promise.reject(new DOMException('Aborted', 'AbortError'));
  }
  return new Promise<T>((resolve, reject) => {
    const onAbort = () => reject(new DOMException('Aborted', 'AbortError'));
    signal.addEventListener('abort', onAbort, { once: true });
    work.then(
      (value) => {
        signal.removeEventListener('abort', onAbort);
        resolve(value);
      },
      (err) => {
        signal.removeEventListener('abort', onAbort);
        reject(err);
      },
    );
  });
}

/** Aborts when EITHER input signal aborts. `AbortSignal.any` (Baseline 2024)
 * covers modern browsers; the manual fallback is for test/older runtimes. */
function anyAbortSignal(
  signals: (AbortSignal | undefined)[],
): AbortSignal | undefined {
  const present = signals.filter((s): s is AbortSignal => !!s);
  if (present.length === 0) return undefined;
  if (present.length === 1) return present[0];
  if (typeof AbortSignal.any === 'function') return AbortSignal.any(present);
  const controller = new AbortController();
  for (const s of present) {
    if (s.aborted) {
      controller.abort();
      break;
    }
    s.addEventListener('abort', () => controller.abort(), { once: true });
  }
  return controller.signal;
}

/** A failed request or a streamed error, with the trace id the user can quote. */
export class AssistantRequestError extends Error {
  status?: number;
  traceId: string;
  messageCode?: string;
  /** Parsed from a 429's `Retry-After` header (seconds → ms), when present. */
  retryAfterMs?: number;

  constructor(
    message: string,
    traceId: string,
    status?: number,
    messageCode?: string,
    retryAfterMs?: number,
  ) {
    super(message);
    this.name = 'AssistantRequestError';
    this.traceId = traceId;
    this.status = status;
    this.messageCode = messageCode;
    this.retryAfterMs = retryAfterMs;
  }
}

async function readErrorBody(
  response: Response,
): Promise<Record<string, unknown>> {
  try {
    return (await response.json()) as Record<string, unknown>;
  } catch {
    return {};
  }
}

/**
 * Parse an SSE byte stream into chunks. Exported for tests: a stream may end
 * without a trailing newline, and non-JSON lines are skipped.
 *
 * CORE-6108 review (Codex) fixes, all in this one function so every caller
 * gets them for free:
 *  - `[DONE]` unconditionally ENDS the generator (`return`), rather than
 *    just being skipped — a server that sends `[DONE]` but keeps the HTTP
 *    body open (no FIN) used to hang here forever waiting for more bytes.
 *  - an inactivity timeout: if no chunk (not even a partial `read()`)
 *    arrives within `inactivityTimeoutMs`, throws AssistantStreamTimeoutError
 *    instead of hanging.
 *  - the reader is always released (`cancel()`) in `finally` — on normal
 *    completion, on `[DONE]`, on the timeout, and when the CALLER stops
 *    iterating early (e.g. it throws on an `{type: 'error'}` chunk, or the
 *    fetch's AbortSignal fires) — `for await...of` calls the iterator's
 *    `return()` on early exit, which runs this `finally`.
 */
export async function* readAssistantStream(
  body: ReadableStream<Uint8Array>,
  inactivityTimeoutMs: number = ASSISTANT_STREAM_INACTIVITY_TIMEOUT_MS,
  onDone?: () => void,
  strictVideo = false,
): AsyncGenerator<AssistantChunk> {
  const reader = body.getReader();
  const decoder = new TextDecoder();
  let buffer = '';
  try {
    while (true) {
      let timeoutHandle: ReturnType<typeof setTimeout> | undefined;
      const timedOut = new Promise<never>((_resolve, reject) => {
        timeoutHandle = setTimeout(
          () => reject(new AssistantStreamTimeoutError()),
          inactivityTimeoutMs,
        );
      });
      let done: boolean | undefined;
      let value: Uint8Array | undefined;
      try {
        ({ done, value } = await Promise.race([reader.read(), timedOut]));
      } finally {
        clearTimeout(timeoutHandle);
      }

      if (value) buffer += decoder.decode(value, { stream: true });
      if (done) buffer += decoder.decode();
      const lines = buffer.split('\n');
      buffer = done ? '' : lines.pop() || '';
      if (utf8Bytes(buffer) > 65536) throw new AssistantRequestError('Oversized SSE line', '');
      for (const line of lines) {
        if (utf8Bytes(line) > 65536) throw new AssistantRequestError('Oversized SSE line', '');
        if (!line.startsWith('data: ')) continue;
        const data = line.slice(6).trim();
        if (!data) continue;
        if (data === '[DONE]') { onDone?.(); return; }
        let parsed: AssistantChunk;
        try { parsed = JSON.parse(data) as AssistantChunk; } catch {
          if (strictVideo) throw new AssistantRequestError('Invalid video JSON', '');
          continue;
        }
        if (parsed?.type === 'page_video') {
          if (utf8Bytes(line + '\n\n') > 65536) throw new AssistantRequestError('Oversized video frame', '');
          const frame = parsePageVideoFrame(parsed);
          if (!frame) throw new AssistantRequestError('Invalid page video frame', '');
          yield frame;
        } else if (parsed?.type === 'outcome') {
          // Ordinary assistant outcomes include rule_preview and other existing values.
          // Video-specific outcome validation belongs to that request below.
          yield parsed;
        } else { yield parsed; }
      }
      if (done) return;
    }
  } finally {
    await reader.cancel().catch(() => {
      // already closed/errored — cancel() itself may throw, releaseLock()
      // below still runs regardless.
    });
    // CORE-6108 review (Codex, round 3): cancel() does not itself guarantee
    // body.locked flips back to false in every runtime — releaseLock() is
    // the actual, spec-defined way to hand the lock back. Without it, a
    // caller (or the next request reusing this body) could see
    // `body.locked === true` after this generator has already "finished".
    try {
      reader.releaseLock();
    } catch {
      // already released — nothing more to do
    }
  }
}

/**
 * POST a conversation to an assistant chat endpoint and stream the answer.
 * Shared by the Settings Assistant and the validation assistant (CORE-6161).
 * Throws AssistantUnavailableError on 404 and AssistantRequestError (with
 * trace id) on any other failure.
 */
export async function* streamAssistantChat(
  path: string,
  payload: Record<string, unknown>,
  signal?: AbortSignal,
  onDone?: () => void,
): AsyncGenerator<AssistantChunk> {
  // The header deadline covers getAuthorizationToken() + fetch() up to the
  // moment response headers arrive — a Promise.race, not just an
  // AbortSignal, because getAuthorizationToken() takes no signal of its
  // own and a hang THERE (before fetch even starts) would otherwise never
  // be caught. Whichever settles first wins; the timeout side also aborts
  // the fetch (via headerDeadline) so a slow-but-eventually-answering
  // request doesn't keep running in the background after we've given up
  // on it. Cleared on every exit so it can never fire once the
  // body-inactivity timeout (readAssistantStream) has taken over.
  const headerDeadline = new AbortController();
  const combinedSignal = anyAbortSignal([signal, headerDeadline.signal]);
  let headerTimeoutHandle: ReturnType<typeof setTimeout> | undefined;
  const headerTimeout = new Promise<never>((_resolve, reject) => {
    headerTimeoutHandle = setTimeout(() => {
      headerDeadline.abort();
      reject(new AssistantStreamTimeoutError());
    }, ASSISTANT_HEADER_TIMEOUT_MS);
  });

  async function getResponse(): Promise<Response> {
    // Shared app-wide refresh: detach on Stop, never cancel it (see
    // detachOnAbort).
    const token = await detachOnAbort(getAuthorizationToken(), signal);
    const orgId = getOrgId();
    return fetch(`${OpenAPI.BASE}${path}`, {
      method: 'POST',
      headers: {
        'Content-Type': 'application/json',
        Accept: 'text/event-stream',
        Authorization: token || '',
        ...(orgId ? { 'X-ORG-ID': orgId } : {}),
      },
      body: JSON.stringify({ org_id: orgId, ...payload }),
      signal: combinedSignal,
    });
  }

  let response: Response;
  try {
    response = await Promise.race([getResponse(), headerTimeout]);
  } finally {
    clearTimeout(headerTimeoutHandle);
  }

  if (response.status === 404) throw new AssistantUnavailableError();

  if (!response.ok) {
    const body = await readErrorBody(response);
    const traceId =
      response.headers.get(TRACE_HEADER) ||
      String(body[TRACE_BODY_FIELD] || '');
    const message = messageFromErrorBody(body, `HTTP ${response.status}`);
    const retryAfterHeader = response.headers.get('retry-after');
    const retryAfterSeconds = retryAfterHeader ? Number(retryAfterHeader) : NaN;
    throw new AssistantRequestError(
      message,
      traceId,
      response.status,
      typeof body.message_code === 'string' ? body.message_code : undefined,
      Number.isFinite(retryAfterSeconds)
        ? retryAfterSeconds * 1000
        : undefined,
    );
  }
  if (!response.body) {
    throw new AssistantRequestError(
      'empty response',
      response.headers.get(TRACE_HEADER) || '',
    );
  }

  const headerTraceId = response.headers.get(TRACE_HEADER) || '';
  for await (const chunk of readAssistantStream(response.body, ASSISTANT_STREAM_INACTIVITY_TIMEOUT_MS, onDone, payload.intent === 'page_video')) {
    if (payload.intent === 'page_video' && headerTraceId && chunkTraceId(chunk) && chunkTraceId(chunk) !== headerTraceId) throw new AssistantRequestError('Video trace mismatch', headerTraceId);
    if (payload.intent === 'page_video' && chunk.type === 'outcome' && (!['answered', 'nothing_found', 'error'].includes(chunk.outcome) || !chunk.trace_id || chunk.trace_id !== chunk.docbits_trace_id)) throw new AssistantRequestError('Invalid video outcome', headerTraceId);
    if (chunk.type === 'error') {
      throw new AssistantRequestError(
        chunk.message,
        chunkTraceId(chunk) || headerTraceId,
        undefined,
        chunk.message_code,
      );
    }
    yield chunk;
  }
}

export const settingsAssistantService = {
  /**
   * Send the conversation and stream the answer. Throws
   * AssistantUnavailableError on 404 and AssistantRequestError (with trace id)
   * on any other failure.
   */
  chat(
    request: AssistantRequest,
    signal?: AbortSignal,
    onDone?: () => void,
  ): AsyncGenerator<AssistantChunk> {
    return streamAssistantChat(
      CHAT_PATH,
      {
        page: request.page,
        messages: request.messages,
        language: request.language,
        conversation_id: request.conversation_id,
        ...(request.intent ? { intent: request.intent } : {}),
      },
      signal,
      onDone,
    );
  },
};

export default settingsAssistantService;
